INSERT INTO `dt01_ics_source_document` (`ID`, `DOC_CODE`, `TITLE`, `VERSION`, `STATUS`, `ISSUED_DATE`, `EFFECTIVE_DATE`, `PUBLISHER`, `IS_ACTIVE`, `LANGUAGE_CODE`, `ICD10_EDITION`, `ICD9CM_EDITION`, `TOTAL_PAGES`, `PDF_PAGE_OFFSET`, `SOURCE_FILE_NAME`, `SOURCE_FILE_SHA256`, `SUPERSEDES_ID`, `NOTES`, `CREATED_AT`, `CREATED_BY`, `UPDATED_AT`, `UPDATED_BY`) VALUES ('1', 'ICS_IDRG', 'Indonesian Coding Standard (ICS) iDRG', 'V1', 'DRAFT', '2025-07-25', NULL, 'Kementerian Kesehatan RI - Pusat Pembiayaan Kesehatan', '1', 'id', 'ICD-10 WHO 2010 + IM', 'ICD-9-CM 2010 + IM', '483', '1', 'Salinan ICS Version 1_25072025 (1).pdf', '5135d7f882d3b756522f5d52a7167de1ff918bda72bd81e91102ea0e51619139', NULL, 'Hak cipta Pusat Pembiayaan Kesehatan Kemenkes RI; dilarang mengcopy/memperjualbelikan isi dan dokumen. Terverifikasi terhadap PDF pada 2026-10-08. STATUS=DRAFT dikonfirmasi watermark sampul \"DRAFT V1\". SHA256 dihitung dari file 8757499 byte. ISSUED_DATE hanya diturunkan dari nama file (25072025) - tidak ada tanggal terbit yang tercetak di dokumen; xmp ModifyDate = 2025-07-27T10:56:29+07:00. TOTAL_PAGES=483 halaman fisik; penomoran cetak 1-482 (sampul tanpa nomor); PDF_PAGE_OFFSET=1 berarti PAGE_PDF = PAGE_PRINTED + 1. dc:title PDF = \"ICS v1\"; frasa \"Indonesian Coding Standard\" tidak ada di dalam dokumen, TITLE adalah nama kanonik sistem Infinite. Producer: Skia/PDF m140 Google Docs Renderer; terenkripsi AES (print:no, copy:yes, change:no).', '2026-10-07 22:23:32', NULL, '2026-10-08 12:22:10', NULL);
INSERT INTO `dt01_ics_mdc` (`ID`, `DOCUMENT_ID`, `MDC_CODE`, `SORT_ORDER`, `IS_ACTIVE`, `NAME_EN`, `NAME_ID`, `EXPLANATION`, `EXAMPLE`, `CHAPTER_NO`, `PAGE_START`, `PAGE_END`, `CREATED_BY`, `UPDATED_BY`, `CREATED_AT`, `UPDATED_AT`) VALUES ('1', '1', '11', '1', '1', 'Diseases and Disorders of the Nervous System', 'SISTEM SYARAF', '● Kasus Pasien yang mendapatkan terapi Thrombolytic Agent Injection/Infusion inputkan kode 99.10 Injection or infusion of thrombolytic agent dalam tindakan iDRG, terutama pada kasus Ischemic Stroke with Thrombolytic.\r\n● Kondisi myopathy (kelemahan otot) yang menyertai diagnosis periodic paralysis tidak dikode secara terpisah, melainkan digabung menjadi satu dengan kode G72.3 (Periodic Paralysis).\r\n● Jika pasien epilepsy dirawat akibat luka yang terjadi saat serangan, maka diagnosis injury menjadi diagnosis utama dan dapat menambahkan kode sebab luar yang relevan dengan kode epilepsy-nya.\r\n● Untuk tindakan di MDC 11 yang berkaitan dengan kelenjar pituitari dan/atau pineal, maka menggunakan kode 07.19 (Other diagnostic procedures on adrenal glands, pituitary gland, pineal gland, and thymus).\r\n● Pada kode tindakan adhesiolysis spinal cord dan nerve root dengan teknik injeksi steroid dan analgetik, jika disesuaikan dengan ICD-9-CM tahun 2010, maka adhesiolysis (Lysis Adhesion) dengan tindakan tumpul, menggunakan jari-jemari, manual mekanik, dan tanpa instrumen merupakan omit code (tidak dikoding).', 'pada kasus operasi pasien, DPJP melakukan tindakan adhesiolysis spinal cord dan nerve root dengan teknik injeksi triamcinolone 80 mg (steroid). Tindakan tersebut adalah adhesiolysis tanpa instrumen (bedah) dan secara mekanik menggunakan agen steroid sehingga tidak dikoding, namun yang dikoding adalah tindakan injeksi triamcinolone 80 mg (steroid) tersebut. Sesuai dengan ICD-9-CM, kode tindakan injeksi triamcinolone 80 mg (steroid) pada spinal root menggunakan kode 03.92 (Injection of other agent into spinal canal).', '3.1', '66', '79', '80b49d3a-71cf-11f1-b543-3a52e86ddc6f', '80b49d3a-71cf-11f1-b543-3a52e86ddc6f', '2026-10-07 22:30:52', '2026-10-08 16:11:39');
INSERT INTO `dt01_ics_mdc` (`ID`, `DOCUMENT_ID`, `MDC_CODE`, `SORT_ORDER`, `IS_ACTIVE`, `NAME_EN`, `NAME_ID`, `EXPLANATION`, `EXAMPLE`, `CHAPTER_NO`, `PAGE_START`, `PAGE_END`, `CREATED_BY`, `UPDATED_BY`, `CREATED_AT`, `UPDATED_AT`) VALUES ('2', '1', '12', '2', '1', 'Diseases and Disorders of the Eye and Adnexa', 'MATA & ADNEXA', 'Pengodean tindakan pengangkatan benda asing pada kornea (*removal foreign superficial cornea*) ditentukan berdasarkan metode yang digunakan selama tindakan. Jika pengangkatan dilakukan tanpa insisi, maka digunakan kode **98.21 (*Removal of superficial foreign body from eye without incision*)**. Apabila prosedur dilakukan dengan bantuan magnet, maka digunakan kode **11.0 (*Magnetic removal of embedded foreign body from cornea*)**.\r\n\r\nPengodean metode pemeriksaan *funduscopy* ditentukan berdasarkan alat yang digunakan. Jika dilakukan dengan menggunakan alat *ophthalmoscope*, menggunakan kode **16.21 (*Ophthalmoscopy*)**. Sedangkan jika menggunakan alat *fundus photography*, menggunakan kode **95.11 (*Fundus Photography*)**.\r\n\r\nGunakan kode lateralisasi untuk kasus mata dengan kode tambahan lateralisasi mata **HL00 (*Right eye*) (IM)** dan **HL01 (*Left eye*) (IM)**.\r\n\r\nPasien kontrol *post-op* mata tanpa tindakan perawatan luka menggunakan kode **Z48.8** sebagai kode diagnosis utama, diikuti diagnosis lain dan tindakan yang relevan dengan episode perawatan pasien.', 'Pasien kontrol *post vitrectomy*, melakukan konsultasi dengan dokter spesialis mata dan tindakan *slit lamp*. Maka kodenya adalah **Z48.0** sebagai kode diagnosis dan **89.07, 95.07** sebagai kode tindakannya.', '3.2', '81', '94', '80b49d3a-71cf-11f1-b543-3a52e86ddc6f', '80b49d3a-71cf-11f1-b543-3a52e86ddc6f', '2026-10-07 22:30:52', '2026-10-08 16:13:39');
INSERT INTO `dt01_ics_mdc` (`ID`, `DOCUMENT_ID`, `MDC_CODE`, `SORT_ORDER`, `IS_ACTIVE`, `NAME_EN`, `NAME_ID`, `EXPLANATION`, `EXAMPLE`, `CHAPTER_NO`, `PAGE_START`, `PAGE_END`, `CREATED_BY`, `UPDATED_BY`, `CREATED_AT`, `UPDATED_AT`) VALUES ('3', '1', '13', '3', '1', 'Diseases and Disorders of the Ear, Nose, Mouth and Throat', 'TELINGA, MULUT, TENGGOROKAN', '● Hilang pendengaran yang terdokumentasi sebagai berat atau sangat berat tanpa diketahui penyebabnya harus selalu dikodekan menggunakan kode dari kategori **H90.- (*Conductive and sensorineural hearing loss*)** atau **H91.- (*Other hearing loss*)**, tergantung pada jenis hilang pendengaran yang didokumentasikan.\r\nKetika penyebab hilang pendengaran berat atau sangat berat telah diketahui, kedua kondisi harus dikodekan. Penempatan kode bergantung pada kondisi utama yang diobati atau diselidiki selama episode perawatan tersebut.\r\n', '', '3.3', '96', '107', '80b49d3a-71cf-11f1-b543-3a52e86ddc6f', '80b49d3a-71cf-11f1-b543-3a52e86ddc6f', '2026-10-07 22:30:52', '2026-10-08 16:15:27');
INSERT INTO `dt01_ics_mdc` (`ID`, `DOCUMENT_ID`, `MDC_CODE`, `SORT_ORDER`, `IS_ACTIVE`, `NAME_EN`, `NAME_ID`, `EXPLANATION`, `EXAMPLE`, `CHAPTER_NO`, `PAGE_START`, `PAGE_END`, `CREATED_BY`, `UPDATED_BY`, `CREATED_AT`, `UPDATED_AT`) VALUES ('4', '1', '14', '4', '1', 'Diseases and Disorders of the Respiratory System', 'SISTEM PERNAFASAN', 'Pada pasien tuberkulosis, baik yang melibatkan sistem pernapasan maupun sistem lainnya, gunakan kode A15–A19 apabila pasien masih menunjukkan sensitivitas terhadap obat. Jika terdapat resistensi terhadap Obat Anti-Tuberkulosis (OAT), kode primer tetap menggunakan A15–A19, dan ditambahkan:a. Kode U88 untuk mencatat adanya resistensi obat, serta b. Kode tambahan IM yang menjelaskan jenis resistensi obat tertentu. Namun demikian, kode A15–A19 tidak boleh digunakan apabila pasien dirawat karena mengalami efek samping akibat penggunaan OAT. Dalam kasus tersebut, gunakan:a. Kode diagnosis yang sesuai untuk menggambarkan efek samping OAT (baik yang bersifat sistemik maupun yang tidak ditentukan), dan b. Kode dari Bab 20 (Chapter XX) untuk mencatat penyebab luar terkait penggunaan OAT. AX 14BX TB Episode of Care U84.31 Tuberculosis with multidrug resistance (IM) U84.32 Tuberculosis with pre extreme drug resistance (IM) U84.33 Tuberculosis with extreme drug resistance (IM) U84.34 Tuberculosis with poly drug resistance (IM) U84.35 Tuberculosis with mono drug resistance (IM) AX 14CX Drug Types U82.20 Respiratory diseases with resistance of betalactamase (ESBL) resistance (IM) U82.80 Respiratory diseases with resistance of betalactam antibiotics (IM) U83.3 Respiratory diseases with resistance to other antibiotics (IM) U84.10 Respiratory diseases with resistance to antifungal drugs (IM) U84.20 Respiratory diseases with resistance to antiviral drugs (IM) U85.0 Respiratory diseases with resistance to antineoplastic drugs (IM)', NULL, '3.4', '109', '118', '80b49d3a-71cf-11f1-b543-3a52e86ddc6f', NULL, '2026-10-07 22:30:52', '2026-10-08 15:29:50');
INSERT INTO `dt01_ics_mdc` (`ID`, `DOCUMENT_ID`, `MDC_CODE`, `SORT_ORDER`, `IS_ACTIVE`, `NAME_EN`, `NAME_ID`, `EXPLANATION`, `EXAMPLE`, `CHAPTER_NO`, `PAGE_START`, `PAGE_END`, `CREATED_BY`, `UPDATED_BY`, `CREATED_AT`, `UPDATED_AT`) VALUES ('5', '1', '15', '5', '1', 'Diseases and Disorders of the Circulatory System', 'JANTUNG DAN PEMBULUH DARAH', 'Pedoman koding dalam iDRG terkait jantung dan pembuluh darah yang memiliki prosedur yang kompleks dalam penanganannya seperti pada kasus pemasangan stent pada pembuluh darah dimana ada sumbatan kemudian dilakukan pelebaran untuk melancarkan peredaran darah. Pada INA-Grouper Tindakan PCI harus dikode dengan ‘ code also ’ yang ada di dalam ICD-9 CM Gambar', NULL, '3.5', '120', '139', '80b49d3a-71cf-11f1-b543-3a52e86ddc6f', NULL, '2026-10-07 22:30:52', '2026-10-08 15:29:50');
INSERT INTO `dt01_ics_mdc` (`ID`, `DOCUMENT_ID`, `MDC_CODE`, `SORT_ORDER`, `IS_ACTIVE`, `NAME_EN`, `NAME_ID`, `EXPLANATION`, `EXAMPLE`, `CHAPTER_NO`, `PAGE_START`, `PAGE_END`, `CREATED_BY`, `UPDATED_BY`, `CREATED_AT`, `UPDATED_AT`) VALUES ('6', '1', '16', '6', '1', 'Diseases and Disorders of the Digestive System', 'SALURAN PENCERNAAN', '● Kasus konstipasi pada ileus maupun obstruksi saluran cerna seharusnya tidak dikode tersendiri karena konstipasi merupakan bagian dari ileus obstruksi tersebut. - Contoh:Pada pasien dengan konstipasi yang disebabkan oleh hernia umbilical dengan obstruksi, cukup diberikan kode K42.0 (Umbilical hernia with obstruction, without gangrene). ● Tidak ada kode kombinasi baik include / exclude secara langsung untuk K29.7 (Gastritis, unspecified) dengan K92.0 (Haematemesis) menjadi K29.0 (Acute haemorrhagic gastritis). Kode K29.0 (Acute haemorrhagic gastritis) digunakan jika sudah tegak dan terkonfirmasi sumber perdarahan berasal dari gaster. ● Appendicitis jika disertai dengan perforasi dan/atau peritonitis, abses peritoneal ataupun sebaliknya diberikan kode gabungan pada K35.-. ● Kasus K83.1 (Obstruction of bile duct pada cholelithiasis) tidak diberikan kode sendiri karena obstruction of bile duct merupakan bagian dari cholelithiasis sehingga cukup dikode K80.-. ● Cholelithiasis yang disertai dengan cholangitis tidak dikode terpisah, melainkan menggunakan kode gabungan K80.3 (Calculus of bile duct with cholangitis). ● Tindakan x-ray dental menggunakan kode 87.11 (Full-mouth x-ray of teeth) atau 87.12 (Other dental x-ray). ● Tindakan enukleasi kista radikuler gigi menggunakan 24.4 (Excission of dental lesion of jaw). ● Tindakan ekstirpasi yang dilakukan pada daerah gingiva/gum/gusi, maka menggunakan kode 24.31 (Excision of lesion or tissue of gum). ● Tindakan laparotomy dan adhesiolysis. - Laparotomy jika sebagai operative approach bersifat “ omit code ” atau tidak perlu dikoding karena merupakan bagian dari kode prosedur lain. - Adhesiolysis perlu dilakukan konfirmasi terlebih dahulu kepada DPJP apakah menggunakan instrumen tajam (surgical), karena pada ICD9CM teknik adhesiolysis yang menggunakan teknik tumpul, digital, manual, mekanik, atau tanpa instrumen bersifat “ omit code ” atau tidak perlu dikoding. ● Peritoneal Adhesiolysis Proc dimana bila bersamaan dengan tindakan appendectomy maka kan masuk dalam kategori Appendectomy Procedures atau Appendectomy Procedures w Complicating PDx seperti diagram dibawah ini:', 'Contoh:Pada pasien dengan konstipasi yang disebabkan oleh hernia umbilical dengan obstruksi, cukup diberikan kode K42.0 (Umbilical hernia with obstruction, without gangrene).', '3.6', '141', '153', '80b49d3a-71cf-11f1-b543-3a52e86ddc6f', NULL, '2026-10-07 22:30:52', '2026-10-08 15:29:50');
INSERT INTO `dt01_ics_mdc` (`ID`, `DOCUMENT_ID`, `MDC_CODE`, `SORT_ORDER`, `IS_ACTIVE`, `NAME_EN`, `NAME_ID`, `EXPLANATION`, `EXAMPLE`, `CHAPTER_NO`, `PAGE_START`, `PAGE_END`, `CREATED_BY`, `UPDATED_BY`, `CREATED_AT`, `UPDATED_AT`) VALUES ('7', '1', '17', '7', '1', 'Diseases and Disorders of the Hepatobiliary System and Pancreas', 'HEPATOBILIER DAN PANKREAS', 'a. Penetapan kode dalam kategori K70.- Alcoholic liver disease, K85.2 Alcohol-induced acute pancreatitis, atau K86.0 Alcohol-induced chronic pancreatitis harus dinyatakan secara jelas bahwa hepatitis atau pankreatitis tersebut disebabkan oleh konsumsi alkohol. Jika seorang pasien memiliki penyakit hati atau pankreatitis yang tidak diketahui penyebabnya dan pasien tersebut memiliki riwayat konsumsi alkohol, diagnosis tidak boleh diasumsikan sebagai akibat konsumsi alkohol tanpa adanya konfirmasi dari dokter yang menangani dan/atau tanpa dokumentasi medis yang menyatakan keterkaitan tersebut. b. Penyakit hati akibat alkohol atau pankreatitis akibat alkohol yang disebabkan karena penggunaan alkohol berlebihan atau ketergantungan alkohol saat ini harus menggunakan kode-kode berikut:○ K70.- (Alcoholic liver disease). ○ K85.2 (Alcohol-induced acute pancreatitis). ○ K86.0 (Alcohol-induced chronic pancreatitis). ○ F10.- (Mental and behavioural disorders due to use of alcohol). Catatan:Penugasan karakter keempat tergantung pada apakah konsultan yang bertanggung jawab telah menyatakan bahwa penyakit hati akibat alkohol disebabkan oleh penggunaan berbahaya alkohol (F10.1) atau ketergantungan (F10.2). c. Penyakit hati akibat alkohol atau pankreatitis akibat alkohol karena penyalahgunaan alkohol sebelumnya harus menggunakan kode-kode berikut dan urutan:○ K70.- (Alcoholic liver disease). ○ K85.2 (Alcohol-induced acute pancreatitis). ○ K86.0 (Alcohol-induced chronic pancreatitis). ○ Z86.4 (Personal history of psychoactive substance abuse). d. Apabila tidak ada informasi mengenai penggunaan atau penyalahgunaan alkohol saat ini atau masa lalu dan hanya menyebutkan jenis penyakit hati akibat alkohol atau pankreatitis akibat alkohol maka kode yang sesuai kategori berikut:○ K70.- (Alcoholic liver disease). ○ K85.2 (Alcohol-induced acute pancreatitis). ○ K86.0 (Alcohol-induced chronic pancreatitis). e. Dalam MDC 17 terdapat kelompok DRG khusus untuk tindakan Cholecystectomy yang disertai dengan tindakan CDE. Oleh karena itu, coder perlu mencermati dokumentasi medis dan riwayat tatalaksana pemberian transfusi. f. Apabila ada tindakan pada grup P17AE, maka dimasukkan ke dalam kelompok DRG Cholecystectomy Proc. Akan tetapi, apabila pengodean group P17AE disertai dengan tambahan dari grup 17PCX, maka akan masuk ke dalam kelompok DRG Cholecystectomy Proc. w CDE Proc. Berikut adalah prosedur yang terdapat di dalam grup P17AE dan AX 17PCX:P17AE Cholecystectomy Proc. 51.21 Other partial cholecystectomy 51.22 Cholecystectomy AX 17PCX CDE Procedures 51.10 Endoscopic retrograde cholangiopancreatography [ERCP] 51.11 Endoscopic retrograde cholangiography [ERC] 51.14 Other closed [endoscopic] biopsy of biliary duct or sphincter of Oddi 51.15 Pressure measurement of sphincter of Oddi 51.64 Endoscopic excision or destruction of lesion of biliary ducts or sphincter of Oddi 51.84 Endoscopic dilation of ampulla and biliary duct 51.85 Endoscopic sphincterotomy and papillotomy 51.86 Endoscopic insertion of nasobiliary drainage tube 51.87 Endoscopic insertion of stent (tube) into bile duct 51.88 Endoscopic removal of stone(s) from biliary tract 51.96 Percutaneous extraction of common duct stones 51.98 Other percutaneous procedures on biliary tract', NULL, '3.7', '155', '161', '80b49d3a-71cf-11f1-b543-3a52e86ddc6f', NULL, '2026-10-07 22:30:52', '2026-10-08 15:29:50');
INSERT INTO `dt01_ics_mdc` (`ID`, `DOCUMENT_ID`, `MDC_CODE`, `SORT_ORDER`, `IS_ACTIVE`, `NAME_EN`, `NAME_ID`, `EXPLANATION`, `EXAMPLE`, `CHAPTER_NO`, `PAGE_START`, `PAGE_END`, `CREATED_BY`, `UPDATED_BY`, `CREATED_AT`, `UPDATED_AT`) VALUES ('8', '1', '18', '8', '1', 'Diseases and Disorders of the Musculoskeletal System and Connective Tissue', 'MUSKULOSKELETAL DAN JARINGAN IKAT', '● Dalam sistem klasifikasi diagnosis penyakit, khususnya dalam sistem muskukokeletal, karakter kelima pada kode diagnosis digunakan untuk memberikan informasi yang lebih rinci terkait jenis dan lokasi keterlibatan jaringan muskulokeletal. Catatan di tingkat bab, kategori, atau kode menunjukkan kode mana yang dapat lebih diperinci dengan penambahan karakter kelima dan lokasi daftar kode karakter kelima dalam klasifikasi. Berikut adalah yang harus diterapkan saat menetapkan karakter kelima dalam system muskuloskeletal:○ Karakter kelima harus digunakan jika data tersebut ada dalam catatan medis dan jika melakukannya menambahkan informasi yang lebih spesifik tentang lokasi. ○ Dalam kasus di mana kode empat karakter sudah spesifik terhadap lokasi dan penambahan karakter kelima tidak akan menambahkan informasi yang lebih spesifik tentang lokasi, karakter kelima tidak diperlukan. ● Berikut adalah contoh kode yang tidak pernah memerlukan penambahan karakter kelima karena spesifik terhadap lokasi. Penambahan karakter kelima tidak akan menambahkan informasi yang lebih spesifik tentang lokasi:○ Idiopathic gout in left knee, gunakan kode M10.06 (Idiopathic gout, lower leg) ○ Pseudosarcomatous fibromatosis. No further information is given, gunakan kode M72.4 (Pseudosarcomatous fibromatosis) ○ Thoracogenic scoliosis, gunakan kode M41.3 (Thoracogenic scoliosis ○ Cervicalgia of cervicothoracic spine, gunakan kode M54.23 (Cervicalgia, cervicothoracic region). ● Cedera lama atau berulang pada sistem muskuloskeletal dan jaringan ikat harus diberikan kode dari bab penyakit sistem muskuloskeletal dan jaringan ikat. Sedangkan cedera saat ini (baru terjadi) pada sistem muskuloskeletal dan jaringan ikat harus dikodekan ke bab cedera, keracunan dan beberapa konsekuensi lain dari penyebab eksternal, kecuali jika Indeks Alfabetis atau Daftar Tabular menunjukkan kode lain yang lebih tepat. Contoh:○ Recurrent dislocation of the elbow joint, gunakan kode M24.42 (Recurrent dislocation and subluxation of joint, upper arm). ○ Stress fracture of lumbar vertebra, gunakan kode M48.46 (Fatigue fracture of vertebra, lumbar region). ● Istilah seperti \'primer\', \'sekunder\', dan \'post-traumatik\' digunakan untuk menjelaskan jenis-jenis khusus arthrosis pada kode M15-M19. Dalam klasifikasi ICD-10, istilah ini penting dan harus disebutkan dalam diagnosis dokter agar kode yang tepat bisa diberikan. Jika istilah tersebut tidak disebutkan, maka kode dengan angka.9 (tidak spesifik) dari kategori yang sesuai akan digunakan ○ Kategori M15.- (Poliarthrosis) harus digunakan untuk arthrosis/osteoartritis dengan penyebutan lebih dari satu situs. Seperti yang ditunjukkan pada catatan eksklusi di kategori M15-M19, osteoartritis tulang belakang dikecualikan dari rentang kode ini (M47.- Spondilosis). ○ Kategori M15.- tidak boleh digunakan untuk mengkodekan keterlibatan bilateral dari satu sendi tunggal; ini harus dikodekan ke kategori M16–M19. ○ Kategori M19.- (Arthrosis) lain harus digunakan untuk mengkodekan osteoartritis di situs lain selain pinggul (M16.- Koksartrosis [arthrosis pinggul]), lutut (M17.- Gonartrosis [arthrosis lutut]), sendi carpometacarpal pertama (M18.- Arthrosis sendi carpometacarpal pertama), atau tulang belakang (M47.- Spondilosis). Contoh:Osteoarthritis (OA) left hip diberi kode M16.9 (Coxarthrosis, unspecified). Secondary osteoarthritis (OA) right knee due to osteochondritis dissecans diberikan kode M17.5 (Other secondary gonarthrosis) dan M93.2 (Osteochondritis dissecans). ● Dalam MDC 18 terdapat DRG khusus untuk pemberian complex procedures untuk tindakan arthroscopy, sehingga koder harus memperhatikan dokumentasi medis, termasuk adanya tindakan pembedahan dan/atau bukti riwayat tata laksana pemberian tranfusi, untuk memastikan pemilihan kode dan DRG yang tepat. - Apabila ada tindakan yang termasuk dalam Arthroscopy Proc, maka masuk ke dalam kelompok DRG Arthroscopy Proc. Akan tetapi apabila pengodean group Arthroscopy Proc disertai dengan tambahan dari grup Complex Procedures for Arthroscopy, maka akan masuk ke dalam kelompok DRG Arthroscopy w/ Complex Proc. Arthroscopy Proc. 80.20 Arthroscopy, unspecified site 80.21 Arthroscopy, shoulder 80.22 Arthroscopy, elbow 80.23 Arthroscopy, wrist 80.24 Arthroscopy, hand and finger 80.25 Arthroscopy, hip 80.26 Arthroscopy, knee 80.27 Arthroscopy, ankle 80.28 Arthroscopy, foot and toe 80.29 Arthroscopy, other specified sites Complex Procedures for Arthroscopy 81.42 Five-in-one repair of knee 81.43 Triad knee repair 81.44 Patellar stabilization 81.45 Other repair of the cruciate ligaments 81.46 Other repair of the collateral ligaments 81.47 Other repair of knee 81.83 Other repair of shoulder 83.63 Rotator cuff repair', 'Contoh:○ Recurrent dislocation of the elbow joint, gunakan kode M24.42 (Recurrent dislocation and subluxation of joint, upper arm). ○ Stress fracture of lumbar vertebra, gunakan kode M48.46 (Fatigue fracture of vertebra, lumbar region). Contoh:Osteoarthritis (OA) left hip diberi kode M16.9 (Coxarthrosis, unspecified). Secondary osteoarthritis (OA) right knee due to osteochondritis dissecans diberikan kode M17.5 (Other secondary gonarthrosis) dan M93.2 (Osteochondritis dissecans).', '3.8', '163', '199', '80b49d3a-71cf-11f1-b543-3a52e86ddc6f', NULL, '2026-10-07 22:30:52', '2026-10-08 15:29:50');
INSERT INTO `dt01_ics_mdc` (`ID`, `DOCUMENT_ID`, `MDC_CODE`, `SORT_ORDER`, `IS_ACTIVE`, `NAME_EN`, `NAME_ID`, `EXPLANATION`, `EXAMPLE`, `CHAPTER_NO`, `PAGE_START`, `PAGE_END`, `CREATED_BY`, `UPDATED_BY`, `CREATED_AT`, `UPDATED_AT`) VALUES ('9', '1', '19', '9', '1', 'Diseases and Disorders of the Skin, Subcutaneous Tissue and Breast', 'KULIT DAN SUBKUTAN', '● Kasus decubitus ulcer L89 yang disebabkan oleh DM Type II diberikan kode E11.5 (Non-insulin-dependent diabetes mellitus,With peripheral circulatory complications). ● Ulkus dekubitus yang tidak disebabkan oleh diabetes mellitus maka menggunakan kode L89. ● Pada kasus pasien dengan abses L02.4 (Cutaneous abscess, furuncle and carbuncle of limb):- Jika dilakukan insisi pada abses tersebut, gunakan kode 86.04 (Other incision with drainage of skin and subcutaneous tissue). - Jika eksisi dilakukan untuk mengambil jaringan,gunakan kode 86.3 (Other local excision or destruction of lesion or tissue of skin and subcutaneous tissue). - Jika dilakukan eksisi dan biopsy, gunakan kode 86.11 (Biopsy of skin and subcutaneous tissue). - Untuk kasus debridemen (membuang jaringan nekrotik), gunakan kode 86.22 (Excisional debridement of wound, infection or burn). ● Pada kasus pasien dengan ulkus thorax dextra, L98.4 (Chronic ulcer of skin, not elsewhere classified), jika pasien dilakukan debridement maka dapat diberikan kode sesuai tindakan debridement yang diberikan. ● Berikut ini adalah tindakan yang biasanya berhubungan dengan MDC 19 Kulit & Subkutan:1. Tindakan 86.22 (Excisional debridement of wound, infection, or burn) dapat dikoding jika pada laporan operasi terdapat eksisi dan debridement pada luka atau luka bakar. 2. Tindakan 86.28 (Nonexcisional debridement of wound, infection, or burn) merupakan tindakan pembersihan jaringan mati dan luka untuk infeksi atau luka bakar. 3. Tindakan rehecting superficial pada luka operasi yang belum sembuh, namun tidak membuka kembali abdomen, dikode menggunakan 86.59 (Closure of skin and subcutaneous tissue of other sites). 4. Tindakan eksisi lesi dengan flap graft. a. Jika eksisi lesi radical (wide) dengan flap closure, maka dikode 86.49 Radical excision of skin lesion) b. Jika eksisi lesi radikal dengan graft (mengambil jaringan dari organ/regio lain) maka dikode 86.4 ditambah dengan kode graft disesuaikan dengan lokasi/anatomi c. Jika eksisi dengan tujuan pengambilan graft, maka dikode graft saja disesuaikan dengan lokasi/anatomi', NULL, '3.9', '201', '213', '80b49d3a-71cf-11f1-b543-3a52e86ddc6f', NULL, '2026-10-07 22:30:52', '2026-10-08 15:29:50');
INSERT INTO `dt01_ics_mdc` (`ID`, `DOCUMENT_ID`, `MDC_CODE`, `SORT_ORDER`, `IS_ACTIVE`, `NAME_EN`, `NAME_ID`, `EXPLANATION`, `EXAMPLE`, `CHAPTER_NO`, `PAGE_START`, `PAGE_END`, `CREATED_BY`, `UPDATED_BY`, `CREATED_AT`, `UPDATED_AT`) VALUES ('10', '1', '20', '10', '1', 'Endocrine, Nutritional and Metabolic Diseases and Disorders', 'ENDOKRIN, NUTRISI DAN METABOLIK', 'Penetapan diagnosis utama dan sekunder harus mengikuti prinsip morbiditas sebagaimana dijelaskan dalam Chapter 2. Pada kasus diabetes mellitus dengan komplikasi ganda, coder wajib memasukkan komplikasi utama yang menjadi alasan utama pasien dirawat sebagai diagnosis sekunder setelah kode E10–E14 dengan karakter keempat “.7”, contohnya E11.7. Pastikan keberadaan atau ketiadaan penyakit terkait komplikasi diabetes mellitus tercantum secara jelas dalam dokumen medis pasien. Pada pasien dengan diagnosis diabetes mellitus tipe 2 disertai penyakit jantung iskemik, kode E11.6 diberikan apabila penyakit jantung iskemik secara definitif disebabkan oleh diabetes mellitus. Untuk menggambarkan secara lebih rinci terkait kondisi kondisi jantung iskemik yang dialami pasien, tambahkan kode I20-I25 sebagai diagnosis sekunder. Apabila penyakit diabetes mellitus tidak berhubungan dengan penyakit jantung iskemik, penentuan diagnosis utama dan sekunder harus mengikuti prinsip morbiditas sebagaimana dijelaskan dalam Chapter 2. Dalam situasi di mana dokter menetapkan diabetes mellitus sebagai diagnosis utama dan penyakit jantung iskemik sebagai diagnosis sekunder, maka gunakan kode E11.9 (diabetes mellitus tipe II tanpa komplikasi) sebagai diagnosis utama dan kode I20–I25 sebagai diagnosis sekunder untuk penyakit jantung iskemik. Dokumentasikan dengan benar mengenai kasus diabetes melitus, dalam iDRG terdapat 2 group tersendiri mengenai diabetes melitus yaitu, Diabetes without Complicated PDx & Diabetes with Complicated PDx, ketepatan dokumentasi klinis dan kode diagnosis akan berpengaruh kepada pengelompokan grouper iDRG.', NULL, '3.10', '215', '228', '80b49d3a-71cf-11f1-b543-3a52e86ddc6f', NULL, '2026-10-07 22:30:52', '2026-10-08 15:29:50');
INSERT INTO `dt01_ics_mdc` (`ID`, `DOCUMENT_ID`, `MDC_CODE`, `SORT_ORDER`, `IS_ACTIVE`, `NAME_EN`, `NAME_ID`, `EXPLANATION`, `EXAMPLE`, `CHAPTER_NO`, `PAGE_START`, `PAGE_END`, `CREATED_BY`, `UPDATED_BY`, `CREATED_AT`, `UPDATED_AT`) VALUES ('11', '1', '21', '11', '1', 'Diseases and Disorders of the Kidney and Urinary Tract', 'DISEASE AND DISORDERS OF THE KIDNEY AND URINARY TRACT', '● Dalam kasus pasien dengan batu (calculus) pada saluran kemih yang disertai infeksi, tidak diperbolehkan menggunakan kode diagnosis secara terpisah. Gunakan kode gabungan yang ada pada N20–N23 (Urolithiasis), sesuai dengan kriteria eksklusi yang tercantum pada subbab N30–N39. ● Pengodean Tindakan Terkait CAPD ○ Untuk pemasangan shunt pada pasien rawat inap dalam rangka terapi Continuous Ambulatory Peritoneal Dialysis (CAPD), gunakan kode 54.94 (Creation of peritoneovascular shunt). ○ Untuk training penggunaan alat CAPD (sebelum alat dipasang secara permanen) pada pasien rawat jalan, gunakan kode 54.98 (Peritoneal dialysis). ○ Untuk kunjungan kontrol atau pengambilan cairan CAPD, tidak perlu menggunakan kode 54.98. ● Pemasangan Akses Hemodialisis ○ Untuk pemasangan Catheter Double Lumen (CDL), gunakan kode 38.95 (Venous catheterization for renal dialysis). ○ Untuk pembuatan akses Cimino, gunakan kode 39.27 (Arteriovenostomy for renal dialysis) ● Kode 55.520 (IM) (Living donor) dan 55.521 (IM) (Cadaver donor) digunakan untuk pemberi donor ginjal disertai dengan Z52.4 (Kidney donor). ● Gout yang menyebabkan nefropati harus dikodekan sebagai berikut, M10.0† (Idiopathic gout) (karakter ke-5 untuk menentukan lokasi) dan N16.8* (Renal tubulo-interstitial disorders in other diseases classified elsewhere). ● Berikut adalah pedoman yang harus diterapkan saat menetapkan kode dari kategori N18.- Penyakit ginjal kronis:○ Ketika penyakit ginjal kronis (CKD) dan penyebabnya yang mendasari didokumentasikan, kedua kondisi harus dikodekan. ○ Penentuan tahap CKD harus mengacu pada dokumentasi tahap yang tercatat oleh dokter dalam rekam medis. Pengode (coder) tidak diperkenankan menggunakan nilai laju filtrasi glomerulus (GFR) secara langsung (seperti 45 mL/menit) atau deskripsi seperti \"penurunan GFR ringan\" untuk menentukan tahap CKD pasien. ○ Jika selama episode perawatan terjadi perubahan tahap CKD, maka kode yang digunakan adalah tahap tertinggi yang tercatat dalam periode tersebut (contoh:dari tahap 1 menjadi tahap 2, maka kodekan sebagai tahap 2). ○ Ketika memberikan kode untuk kondisi yang termasuk dalam kategori N18.- yaitu Penyakit Ginjal Kronis yang disebabkan oleh hipertensi, maka harus juga diberikan kode dari kategori I12.- yaitu Penyakit Ginjal Hipertensi (atau I13.- jika pasien juga mengalami penyakit jantung akibat hipertensi). Penentuan diagnosis utama tergantung pada kondisi apa yang menjadi fokus utama perawatan atau pemeriksaan medis. ○ Saat mengkodekan kondisi apapun yang dapat diklasifikasikan ke kategori N18.- Penyakit ginjal kronis pada pasien dengan hipertensi yang tidak disebabkan oleh hipertensi, sebuah kode dari kategori I12.- tidak boleh ditetapkan dan hipertensi harus dikodekan secara terpisah. ● Dalam MDC 21 terdapat DRG khusus untuk tindakan Extracorporeal shockwave lithotripsy (ESWL), sehingga koder harus memperhatikan dokumentasi medis dan bukti tata laksana tindakan ESWL. - Ketika terdapat tindakan yang masuk ke dalam MDC 21 dan disertai dengan tindakan ESWL dengan kode 98.51, maka akan masuk ke dalam DRG dengan deskripsi w/ESWL, misalkan:○ Ureteroscopy Proc. w/ ESWL ○ Cystourethroscopy Proc. w/ ESWL ○ Urinary Stone/Obstruction w/ ESWL', 'contoh:dari tahap 1 menjadi tahap 2, maka kodekan sebagai tahap 2). ○ Ketika memberikan kode untuk kondisi yang termasuk dalam kategori N18.- yaitu Penyakit Ginjal Kronis yang disebabkan oleh hipertensi, maka harus juga diberikan kode dari kategori I12.- yaitu Penyakit Ginjal Hipertensi (atau I13.- jika pasien juga mengalami penyakit jantung akibat hipertensi). Penentuan diagnosis utama tergantung pada kondisi apa yang menjadi fokus utama perawatan atau pemeriksaan medis. ○ Saat mengkodekan kondisi apapun yang dapat diklasifikasikan ke kategori N18.- Penyakit ginjal kronis pada pasien dengan hipertensi yang tidak disebabkan oleh hipertensi, sebuah kode dari kategori I12.- tidak boleh ditetapkan dan hipertensi harus dikodekan secara terpisah.', '3.11', '230', '236', '80b49d3a-71cf-11f1-b543-3a52e86ddc6f', NULL, '2026-10-07 22:30:52', '2026-10-08 15:29:50');
INSERT INTO `dt01_ics_mdc` (`ID`, `DOCUMENT_ID`, `MDC_CODE`, `SORT_ORDER`, `IS_ACTIVE`, `NAME_EN`, `NAME_ID`, `EXPLANATION`, `EXAMPLE`, `CHAPTER_NO`, `PAGE_START`, `PAGE_END`, `CREATED_BY`, `UPDATED_BY`, `CREATED_AT`, `UPDATED_AT`) VALUES ('12', '1', '22', '12', '1', 'Diseases and Disorders of the Male Reproductive System', 'SISTEM REPRODUKSI PRIA', 'Dalam proses pengkodean tindakan medis di MDC ini, terdapat kode Indonesian Modification (IM) yang telah ditetapkan oleh Kementerian Kesehatan Republik Indonesia untuk mendokumentasikan tindakan khusus dengan lebih akurat. Beberapa kode Indonesian Modification yang digunakan antara lain:60.50 Laparoscopic radical prostatectomy (IM) 64.970 Revision artificial erection device (IM) 17.25 Laparoscopic repair inguinal hernia (IM) 63.10 Microligation for varicocele (IM) 63.11 Laparoscopic varicocele ligation (IM) 86.060 Insertion prostatic stent/coil with ultrasound control (IM) 86.061 Insertion prostatic stent/coil with visual (IM) 60.22 Transurethral needle ablation prostate (IM) 60.23 Cryoablation of prostate (IM) 60.24 Transurethral electric vaporization prostate (IM) 60.25 High intensity focused ultrasound prostate (IM) 51.120 Laparoscopic biopsy gonad (IM) 60.290 Transurethral resection of ejaculatory duct (TURED) (IM) 62.31 Laparoscopic orchiectomy (IM) 62.50 Laparoscopic orchidopexy (IM) 62.52 Laparoscopic orchidopexy fowler stephen (IM) 99.960 Microsurgical testicular sperm extraction (micro-TESE) (IM) Detail lengkap mengenai kode Indonesian Modification dapat dilihat dalam daftar yang telah diterbitkan oleh Kemenkes RI. Penggunaan kode IM wajib dilakukan sesuai dengan tindakan yang terdokumentasi dalam rekam medis pasien untuk memastikan akurasi dan validitas data. Pemanfaatan kode IM ini sangat penting dalam pengembangan sistem DRG (Diagnosis Related Group) kedepannya, untuk meningkatkan kualitas pengelolaan data pembiayaan kesehatan nasional. copyright@ Pusat pembiayaan kesehatan Kemenkes RI. Dilarang mengcopy atau memperjualbelikan isi dan dokumen ini dalam bentuk apapun 237', NULL, '3.12', '238', '238', '80b49d3a-71cf-11f1-b543-3a52e86ddc6f', NULL, '2026-10-07 22:30:52', '2026-10-08 15:29:50');
INSERT INTO `dt01_ics_mdc` (`ID`, `DOCUMENT_ID`, `MDC_CODE`, `SORT_ORDER`, `IS_ACTIVE`, `NAME_EN`, `NAME_ID`, `EXPLANATION`, `EXAMPLE`, `CHAPTER_NO`, `PAGE_START`, `PAGE_END`, `CREATED_BY`, `UPDATED_BY`, `CREATED_AT`, `UPDATED_AT`) VALUES ('13', '1', '23', '13', '1', 'Diseases and Disorders of the Female Reproductive System', 'SISTEM REPRODUKSI WANITA', '● Perhatikan kriteria include dan exclude yang berkaitan dengan MDC 23. Untuk kasus eksisi kista dan adhesiolisis pada kista vagina N89.8:○ Tindakan prosedur eksisi pada vagina untuk pengangkatan kista tanpa pengambilan sampel jaringan untuk pemeriksaan histopatologi maka gunakan kode 70.33. ○ Tindakan prosedur pengambilan jaringan untuk biopsy maka gunakan kode 70.24. ○ Tindakan prosedur pengangkatan kista secara keseluruhan dan biopsy maka gunakan kode 70.33 dan 70.24. ● Dalam proses pengkodean tindakan medis pada MDC ini, sangat penting untuk mencatat secara jelas dan rinci dalam rekam medis mengenai jenis teknik tindakan yang digunakan, apakah dilakukan dengan teknik laparoskopi atau non-laparoskopi. Hal ini dikarenakan sistem iDRG MDC membedakan pengelompokan (grouping) pasien berdasarkan teknik tindakan tersebut. sebagai contoh tindakan 68.61 Laparoscopic radical abdominal hysterectomy & 68.71 Laparoscopic radical vaginal hysterectomy [LRVH] merupakan prosedur khusus untuk DC Laparoscopic Radical Hysterectomy Proc.', NULL, '3.13', '240', '255', '80b49d3a-71cf-11f1-b543-3a52e86ddc6f', NULL, '2026-10-07 22:30:52', '2026-10-08 15:29:50');
INSERT INTO `dt01_ics_mdc` (`ID`, `DOCUMENT_ID`, `MDC_CODE`, `SORT_ORDER`, `IS_ACTIVE`, `NAME_EN`, `NAME_ID`, `EXPLANATION`, `EXAMPLE`, `CHAPTER_NO`, `PAGE_START`, `PAGE_END`, `CREATED_BY`, `UPDATED_BY`, `CREATED_AT`, `UPDATED_AT`) VALUES ('14', '1', '24', '14', '1', 'Pregnancy, Childbirth and the Puerperium', 'KEHAMILAN, PERSALINAN DAN NIFAS', '● Pada kasus persalinan yang memiliki penyulit, maka yang dijadikan diagnosis utama adalah penyulit persalinannya, sedangkan kode O80-O84 (Delivery) digunakan sebagai diagnosis sekunder untuk menunjukkan metode persalinan. Jika tidak terdapat komplikasi atau penyulit persalinan lainnya, maka kode O80-O84 (Delivery) dapat digunakan sebagai diagnosis utama. Untuk kode dari kategori Z37.- merupakan hasil persalinan (outcome delivery) yang harus ditetapkan pada episode persalinan ibu, untuk mengidentifikasi hasil akhir persalinan, seperti kelahiran hidup tunggal, kelahiran mati atau kelahiran kembar. Kode Z37.- dapat ditempatkan sebagai diagnosis sekunder namun tidak boleh sebagai diagnosis utama. ● Untuk kasus abortus yang dilakukan kuretase, kode 69.02 (Dilation and curettage following delivery or abortion) digunakan untuk terminasi kehamilan akibat abortus, sedangkan kode 69.09 (Other dilation and curettage) digunakan untuk kuretase selain abortus. Kode dalam kategori Z37.- hasil persalinan (outcome delivery) tidak boleh digunakan pada pasien yang telah menjalani pengguguran kehamilan atau mengalami keguguran yang mengakibatkan kelahiran janin mati saat berada di rumah sakit. Kode O95–O99 digunakan jika ada kondisi penyakit atau kelainan yang menyertai kehamilan atau persalinan. ● Prosedur induksi persalinan dengan menggunakan obat-obatan menggunakan kode 73.4 (Medical induction of labor). Jika induksi persalinan dengan alat dilatasi servikal menggunakan kode 73.1 (Other surgical induction of labour), sedangkan akselerasi persalinan pada saat pasien sudah dalam kondisi persalinan menggunakan kode 73.99 (Other operations assisting delivery, other). ● Persalinan normal pada pasien dengan Riwayat SC sebelumnya, menggunakan kode O75.7 (Vaginal delivery following previous cesarean section). Sedangkan shock pasca bersalin menggunakan kode O75.1 (Shock during or following labour and delivery). ● Prosedur episiotomy menggunakan kode 73.6 (Episiotomy). Tindakan episiorrhaphy tidak dikoding terpisah apabila dilakukan setelah episiotomi pada episode perawatan yang sama. Tindakan repair pada rutin episiotomy saat persalinan normal menggunakan kode 73.6. Jika didapatkan robekan perineum spontan ataupun robekan perineum tambahan diluar episiotomy, maka kode O70.- (Perineal laceration during delivery) harus ditambahkan, serta kode 75.69 (Repair of other current obstetric laceration) juga ditambahkan jika dilakukan repair perineum. ● Jika dilakukan tindakan lain bersamaan dengan tindakan SC, dapat ditambahkan kode di bawah ini:- Kode 66.39 (Other bilateral destruction or occlusion of fallopian tubes) untuk sterilisasi tuba - Kode 69.99 (Other operations on cervix and uterus) untuk B-Lynch atau tindakan jahitan kompresi uterus lainnya - Kode 68.39 (Other and unspecified subtotal abdominal hysterectomy, NOS) untuk subtotal histerektomi - Kode 68.4 (Total abdominal hysterectomy) untuk total histerektomi - Kode 68.29 (Other excision or destruction of lesion of uterus) untuk eksisi uterus pada kasus reseksi uterus pada plasenta akreta. ● Jika didapatkan upaya untuk melakukan devaskularisasi pada uterus untuk menurunkan jumlah perdarahan, dapat juga dikode 38.86 untuk ligasi arteri iliaka / uterina / neovaskularisasi uterovesika dan kode 38.84 untuk kompresi aorta. ● Jika terdapat multiple delivery dengan 2 kombinasi cara bersalin yang berbeda, gunakan kode O84.8 untuk melengkapi kaidah koding persalinan. ● Kriteria kondisi yang menggunakan kode O80:- Kode O80 Single spontaneous delivery hanya digunakan ketika persalinan sepenuhnya normal dengan satu kelahiran hidup, tidak ada komplikasi pasca persalinan, dan komplikasi antepartum selama kehamilan harus sudah teratasi sebelum waktu persalinan. Berikut merupakan kriteria-kriteria yang harus dipenuhi agar kode O80 dapat digunakan dengan benar:a. Persalinan sepenuhnya normal (memerlukan bantuan minimal atau tidak sama sekali, dengan atau tanpa episiotomi) b. Tidak terdapat manipulasi janin (misalnya:rotasi) atau instrumentasi (forsep) c. Terjadi persalinan spontan, melalui kepala dan vagina d. Presentasi saat persalinan hanya bisa berupa cephalic (kepala) atau oksipital. Istilah seperti “ right occipito-anterior (ROA)”, “ left occipito-anterior (LOA)”, “ right occipito-posterior (ROP)”, “ left occipito-posterior (LOP)”, dan “ vertex ” menggambarkan presentasi oksipital. Presentasi lainnya seperti bokong, wajah, atau alis (dahi), tidak memperbolehkan penggunaan kode O80. e. Setiap komplikasi antepartum yang dialami selama kehamilan harus sudah diatasi sebelum waktu persalinan f. Tidak terdapat kelainan yang mungkin terjadi pada persalinan atau melahirkan g. Tidak ada komplikasi pasca persalinan yang mungkin terjadi h. Tidak boleh dilakukan dilakukan prosedur selain prosedur berikut ini:episiotomi tanpa forsep, episiorrhaphy, amniotomy (pecahnya selaput ketuban secara buatan), persalinan dengan bantuan manual tanpa forsep, pemberian analgesik dan/atau anestesi, pemantauan janin, induksi persalinan (jika tidak ada indikasi medis), dan sterilisasi. Jika prosedur lain dilakukan, kode O80 tidak dapat ditetapkan. i. Outcome of delivery harus berupa kelahiran hidup tunggal (Z37.0 Single live birth). Jika terjadi kelahiran ganda atau kelahiran mati, kode O80 tidak dapat ditetapkan.', NULL, '3.14', '257', '308', '80b49d3a-71cf-11f1-b543-3a52e86ddc6f', NULL, '2026-10-07 22:30:52', '2026-10-08 15:29:50');
INSERT INTO `dt01_ics_mdc` (`ID`, `DOCUMENT_ID`, `MDC_CODE`, `SORT_ORDER`, `IS_ACTIVE`, `NAME_EN`, `NAME_ID`, `EXPLANATION`, `EXAMPLE`, `CHAPTER_NO`, `PAGE_START`, `PAGE_END`, `CREATED_BY`, `UPDATED_BY`, `CREATED_AT`, `UPDATED_AT`) VALUES ('15', '1', '25', '15', '1', 'Newborns and Other Neonates with Conditions Originating in the Perinatal Period', 'PERINATOLOGI', 'Dalam pengodean MDC 25, selain kode diagnosis dan prosedur yang digunakan, berat badan bayi juga memiliki pengaruh pada hasil grouper. Contohnya, jika berat badan bayi yang dimasukkan adalah 2500 gram, maka bayi tersebut akan masuk ke dalam kelompok grouper dengan kategori berat badan > 2499. Bayi baru lahir/neonatus yang tidak sehat selama episode kelahiran sampai dengan usia 28 hari pada umumnya menggunakan kode P, tetapi tidak menutup kemungkinan menggunakan kode lain, dan menggunakan kode Z38.- Bayi lahir hidup menurut tempat kelahiran sebagai kode diagnosis tambahan. Untuk Bayi lahir normal hanya diberikan kode Z38.- saja dan diklaim satu episode dengan ibunya. Tabel X. Contoh kasus penginputan iDRG MDC 25 Contoh 1-25 Bayi tunggal lahir hidup dari persalinan SC, mengalami asfiksia berat dengan nilai apgar 2. Diagnosis Dokter Pengode Memberi Kode Diagnosis Primer Asfiksia berat P21.0 Severe birth asphyxia Diagnosis sekunder - P03.4 Fetus and newborn affected by cesarean delivery Z38.0 Singleton, born in hospital Tindakan Ventilator 80 jam 96.71 Continuous invasive mechanical ventilation for less than 96 consecutive hours', NULL, '3.15', '310', '317', '80b49d3a-71cf-11f1-b543-3a52e86ddc6f', NULL, '2026-10-07 22:30:52', '2026-10-08 15:29:50');
INSERT INTO `dt01_ics_mdc` (`ID`, `DOCUMENT_ID`, `MDC_CODE`, `SORT_ORDER`, `IS_ACTIVE`, `NAME_EN`, `NAME_ID`, `EXPLANATION`, `EXAMPLE`, `CHAPTER_NO`, `PAGE_START`, `PAGE_END`, `CREATED_BY`, `UPDATED_BY`, `CREATED_AT`, `UPDATED_AT`) VALUES ('16', '1', '26', '16', '1', 'Diseases and Disorders of the Blood and Blood-Forming Organs', 'PENYAKIT PADA DARAH DAN ORGAN PEMBENTUK DARAH', '● Jika pasien dengan Thalasemia Mayor, pada saat kontrol ulang diberikan obat kelasi besi (Deferiprone, Deferoxamine dan Deferasirox) maka perlu diinput sebagai pasien rawat jalan dengan menggunakan kode D56.1 (Beta thalassaemia) sebagai diagnosis utama. ● Dalam MDC 26, terdapat DRG khusus untuk pemberian transfusi faktor koagulasi dan transfusi darah sehingga koder harus memperhatikan dokumentasi medis dan bukti tatalaksana pemberian transfusi. - Apabila terdapat diagnosis yang masuk ke dalam MDC 26 dan disertai dengan tindakan transfusi darah dengan kode 99.03, 99.04, dan 99.05, maka dapat dimasukkan ke dalam DRG dengan diagnosis Red Blood Cell Disorders w/ Blood Transfusion atau Coagulation Disorders w/ Blood Transfusion atau Immunity Disorders w/ Blood Transfusion. - Apabila terdapat diagnosis yang masuk ke dalam kelompok coagulation disorders dan disertai dengan tindakan transfusi faktor koagulasi dengan kode 99.06, maka dapat dimasukkan ke dalam DRG Coagulation Disorders w/ Coagulation Factor Transfusion.', NULL, '3.16', '319', '323', '80b49d3a-71cf-11f1-b543-3a52e86ddc6f', NULL, '2026-10-07 22:30:52', '2026-10-08 15:29:51');
INSERT INTO `dt01_ics_mdc` (`ID`, `DOCUMENT_ID`, `MDC_CODE`, `SORT_ORDER`, `IS_ACTIVE`, `NAME_EN`, `NAME_ID`, `EXPLANATION`, `EXAMPLE`, `CHAPTER_NO`, `PAGE_START`, `PAGE_END`, `CREATED_BY`, `UPDATED_BY`, `CREATED_AT`, `UPDATED_AT`) VALUES ('17', '1', '27', '17', '1', 'Myeloproliferative Diseases and Disorders', 'PENYAKIT DAN GANGGUAN PROLIFERATIF', 'Kelompok diagnosis myeloproliferatif (MPD) mencakup beberapa kondisi yang dapat berkembang menjadi keganasan, seperti leukemia mieloid kronis (LMK) dan mielofibrosis primer. LMK adalah salah satu bentuk keganasan darah yang berkembang dari MPD, ditandai oleh proliferasi sel-sel myeloid yang abnormal dalam sumsum tulang. Hal ini disebabkan oleh mutasi genetik seperti translokasi kromosom Philadelphia, yang menghasilkan protein BCR-ABL yang onkogenik. Pasien dengan LMK dapat mengalami peningkatan jumlah sel darah putih, anemia, dan trombositosis. Selain itu, juga mengalami gejala seperti kelelahan, berat badan turun, dan pembesaran limpa. Sementara itu, myelofibrosis primer adalah kondisi MPD yang ditandai oleh fibrosis atau penggantian jaringan normal sumsum tulang oleh jaringan parut. Kondisi ini dapat berkembang menjadi keganasan, terutama ketika mutasi genetik tambahan terjadi, seperti mutasi genetik dalam gen JAK2, MPL, atau CALR. Pasien dengan mielofibrosis primer dapat mengalami gejala seperti kelelahan, pembesaran limpa atau hati, dan peningkatan risiko infeksi dan perdarahan. Terkadang, mielofibrosis primer juga dapat berkembang menjadi leukemia mieloid akut (AML). Pemahaman akan potensi keganasan MPD penting dalam manajemen dan perawatan pasien. Dokter harus memantau pasien secara ketat untuk deteksi dini perkembangan keganasan dan merencanakan intervensi yang sesuai. Pemantauan dapat melibatkan terapi target yang lebih agresif atau transplantasi sumsum tulang. Tindak lanjut rutin dengan pemeriksaan fisik, tes darah, dan pemantauan genetik diperlukan untuk mengelola risiko dan memaksimalkan hasil pasien.', NULL, '3.17', '325', '325', '80b49d3a-71cf-11f1-b543-3a52e86ddc6f', NULL, '2026-10-07 22:30:52', '2026-10-08 15:29:51');
INSERT INTO `dt01_ics_mdc` (`ID`, `DOCUMENT_ID`, `MDC_CODE`, `SORT_ORDER`, `IS_ACTIVE`, `NAME_EN`, `NAME_ID`, `EXPLANATION`, `EXAMPLE`, `CHAPTER_NO`, `PAGE_START`, `PAGE_END`, `CREATED_BY`, `UPDATED_BY`, `CREATED_AT`, `UPDATED_AT`) VALUES ('18', '1', '28', '18', '1', 'Infectious and Parasitic Diseases and Disorders', 'PENYAKIT INFEKSI DAN PARASIT', '● Pada kasus typhoid dalam kehamilan yang dirawat oleh dokter spesialis penyakit dalam, jika tidak ada diagnosis lainnya, berikan kode untuk typhoid pada kehamilan yaitu O98.8 Other maternal infectious and parasitic diseases complicating pregnancy, childbirth and the puerperium sebagai diagnosis utama dan A01.0 Typhoid fever sebagai diagnosis sekunder. ● Tidak ada kode gabung antara typhoid dengan diare menjadi A02.0 karena instruksi exclude pada volume I sub bab other gastroenteritis and colitis or infectious and unspecified origin (A09) yang menyatakan “gastroenteritis and colitis due to bacterial, protozoal, viral and other specified infectious agents” mengarah pada kode spesifik sesuai dengan organismenya (A00-A08). Sehingga kode A09 seharusnya tidak dikoding lagi apabila sudah ada typhoid fever (A01.0) yang tegak secara medis. ● Perlu diperhatikan lagi penggunaan kode A09, A09.0 dan A09.9 digunakan untuk diare yang penyebabnya tidak diketahui. Jika penyebab diare diketahui maka menggunakan kode yang spesifik. Jika disebabkan oleh bakteri, protozoa, virus dan organisme spesifik lainnya berada dalam A00-A08. Contoh GE akibat infeksi Entamoeba Histolytica disebut disentri dan dikoding dengan menggunakan kode A06.0 tanpa A09. ● Kasus TB dengan Pneumonia/Bronchopneumonia menggunakan kode gabungan A16.2 (Tuberculosis of lung), dengan penjelasan kondisi tuberculous pneumonia sudah termasuk (include) dalam kode A16.2. Perlu dijadikan perhatian pada sub bab A15-A19 termasuk pada kondisi infeksi yang disebabkan oleh Mycobacterium Tuberculosis dan mycobacterium bovis:○ Kode A15.1 (Tuberculosis of lung, confirmed by culture only) hanya digunakan pada TB Paru yang sudah ditegakkan melalui kultur. ○ A15.2 (Tuberculosis of lung, confirmed histologically) hanya digunakan pada TB Paru yang sudah ditegakkan melalui pemeriksaan histologis. ○ A15.3 (Tuberculosis of lung, confirmed by unspecified means) hanya digunakan pada TB Paru yang sudah tegak namun tidak dapat dipastikan secara bakteriologi ataupun histologis. ● Kasus TB dengan malnutrisi terdapat kode kombinasi hanya untuk kasus marasmus yaitu kode E41 (Nutritional marasmus). ● Kode pneumonia (J18.9) dengan TB Paru (A15.2 atau A16.2) sudah termasuk dalam kode A15.2 atau A16.2 dengan kepastian dari pemeriksaan penunjang. Jika ada sepsis / Septicaemia, unspecified (A41.9) dengan Pneumonia (J18.9) tidak ada instruksi includes / exclude secara langsung untuk kode gabungan antara keduanya. ● Sepsis dengan shock sepsis sesuai dengan ICD-10 sudah termasuk kedalam A41.9 tanpa perlu menambahkan R57.2 (Septic shock). ● Jika pasien mengalami shock kardiogenik bersamaan dengan sepsis, pengode tidak boleh hanya mengkode sepsis saja. Dalam kaidah morbiditas untuk klaim, tidak ada aturan includes dan excludes yang menggabungkan kode sepsis (A41.9) dengan kode shock kardiogenik (R57.0) menjadi satu kode. Jadi, kedua kode tersebut harus dicatat secara terpisah. ● Begitu juga dengan shock hipovolemik (R57.1) yang terjadi bersamaan dengan sepsis (A41.9), tidak ada aturan yang menggabungkan keduanya menjadi satu kode. Oleh karena itu, kode sepsis dan kode shock hipovolemik juga harus dikodekan secara terpisah ● Jika dokter memberikan diagnosis hanya gas gangrene, dapat dikode R02 Gangrene, not elsewhere classified. Jika dokter memberikan diagnosis gas gangrene dikode A48.0 dan gangrene pada diabetes mellitus diberikan kode E10-E14 (sesuai dengan jenis diabetes mellitus) dengan digit terakhir.5 ● Jika dokter memberikan diagnosis ancylostomiasis, gunakan kode B76.0 termasuk di dalamnya uncinariasis. Jika dokter memberikan diagnosis askariasis atau infeksi cacing gelang, gunakan kode B77.-. Perhatikan kode dagger asterisk dengan pneumonia dan komplikasi intestinal. ● Sepsis adalah reaksi tubuh terhadap infeksi di mana tubuh menyerang organ dan jaringan sendiri. Kondisi ini sangat berbahaya dan perlu penanganan segera. Sepsis bukanlah infeksi itu sendiri. Aturan dan cara mengenali serta mengobati sepsis terus berubah dari waktu ke waktu. Di berbagai negara, pemahaman dan cara mencatat sepsis juga berbeda-beda. Sepsis sulit didiagnosis karena tidak ada tes laboratorium khusus yang bisa dengan cepat dan pasti memastikan apakah seseorang mengalami sepsis atau tidak, terutama saat pengobatan harus segera dimulai. Untuk membantu mengenali pasien yang mungkin mengalami sepsis dan membutuhkan penanganan cepat, ada berbagai alat, sistem penilaian, dan pedoman yang digunakan oleh tenaga medis. ● Jika pasien didiagnosis sepsis, maka kode yang secara khusus menunjukkan sepsis harus selalu dicantumkan. Jika kode yang dipakai tidak secara khusus menyebut sepsis (misalnya A54.8 untuk infeksi gonokokal lainnya yang juga bisa menyebabkan sepsis), maka kode sepsis harus ditambahkan sebagai kode sekunder agar kondisi pasien tercatat lengkap. ● Jika dokter menyebut istilah seperti urosepsis, sepsis bilier, sepsis dada, sepsis intraokular, atau sepsis urinari, ini berarti pasien mengalami sepsis sekaligus infeksi di organ tertentu, sehingga dalam kasus ini kedua kondisi tersebut harus dikodekan. Namun, jika pasien hanya mengalami infeksi tanpa sepsis, misalnya infeksi saluran kemih atau infeksi dada tanpa tanda sepsis, maka kode sepsis tidak boleh digunakan. ● Jika sepsis terjadi karena adanya alat medis, implan, atau graft (seperti penggantian pinggul, kateter, stoma trakeostomi, atau kateter hemodialisis), ini berarti pasien memiliki sepsis dan infeksi di lokasi alat tersebut. Maka, kode untuk sepsis dan lokasi infeksi harus dicatat. ● Sepsis tidak selalu menjadi kondisi utama yang diobati, jadi urutan kode sepsis, infeksi, dan kondisi lain bisa disesuaikan sesuai dengan fokus pengobatan pasien. ● Setiap kali dokter mencatat syok septik dalam catatan medis, kode R57.2 Syok septik harus ditambahkan sebagai kode sekunder setelah kode yang menunjukkan sepsis. ● Untuk diagnosis sepsis berat, gunakan kode berikut dengan penempatan yang tepat:○ Kode A41.- untuk sepsis (termasuk jenis sepsis tertentu yang tercatat dalam catatan medis) ○ Kode R65.1 untuk sindrom respons inflamasi sistemik akibat infeksi yang disertai kegagalan organ. ● Berikut merupakan beberapa contoh kasus sepsis:1) Sepsis urinaria (konsultan yang bertanggung jawab mengkonfirmasi sepsis dan infeksi saluran kemih) karena streptokokus grup A, dengan syok septik dan kegagalan ginjal dan hati. A40.0 Sepsis due to Streptococcus, group A N39.0 Urinary tract infection, site not specified B95.0 Streptococcus, group A, as the cause of diseases classified to other chapters R57.2 Septic shock N19.X Unspecified kidney failure K72.9 Hepatic failure, unspecified 2) Sepsis urinaria dan sepsis bilier (konsultan yang bertanggung jawab mengkonfirmasi infeksi saluran kemih dan kolangitis tanpa sepsis) N39.0 Urinary tract infection, site not specified K83.0 Cholangitis 3) Sepsis setelah keguguran yang terlewat selama episode yang sama O02.1 Missed abortion O08.0 Genital tract and pelvic infection following abortion and ectopic and molar pregnancy A41.9 Sepsis, unspecified 4) Pasien dengan infeksi streptokokus pada saluran kemih yang berkembang menjadi sepsis berat karena streptokokus. Cedera ginjal akut, kegagalan hati, dan syok septik. A40.9 Streptococcal sepsis, unspecified R65.1 Systemic Inflammatory Response Syndrome of infectious origin with organ failure N39.0 Urinary tract infection, site not specified B95.5 Unspecified streptococcus as the cause of diseases classified to other chapters N17.9 Acute renal failure, unspecified K72.9 Hepatic failure, unspecified R57.2 Septic shock 5) Sepsis stafilokokus negatif koagulase pasca operasi karena infeksi kateter hemodialisis stafilokokus negatif koagulase. A41.1 Sepsis due to other specified staphylococcus T82.7 Infection and inflammatory reaction due to other cardiac and vascular devices, implants and grafts B95.7 Other staphylococcus as the cause of diseases classified to other chapters Y83.1 Surgical operation with implant of artificial internal device (Operasi bedah dan prosedur bedah lainnya sebagai penyebab reaksi abnormal pasien, atau komplikasi kemudian, tanpa disebutkan ketidakberuntungan pada saat prosedur, operasi bedah dengan pemasangan perangkat internal buatan). ● Untuk kasus Dengue Shock Syndrome (DSS) menggunakan kode A91.0 Dengue Haemorrhagic Fever, with shock sebagai diagnosis utama, penambahan diagnosis syok disesuaikan dengan penegakan diagnosis dan tatalaksana yang diberikan. ● Berikut ini harus diterapkan saat melakukan pengodean penyakit HIV simtomatik (aktif):○ Hanya gunakan satu kode dari kategori B20-B24 Penyakit Human Immunodeficiency Virus [HIV] jika kode tersebut sudah mewakili diagnosis HIV maupun penyakit yang ditimbulkan oleh HIV (kecuali HIV menyebabkan neoplasma ganas) ○ Jika kode penyakit HIV dari kategori B20-B24 tidak sepenuhnya mengklasifikasikan baik HIV maupun kondisi yang disebabkan oleh HIV, kode yang mengklasifikasikan kondisi juga harus dituliskan setelah kode penyakit HIV. ○ Jika terdapat lebih dari satu kondisi yang disebabkan oleh HIV yang diklasifikasikan ke kategori yang sama di B20-B22, sub-karakter.7 dari kategori yang sesuai harus digunakan, diikuti oleh kode yang mengklasifikasikan kondisi spesifik. ○ Ketika melakukan pengodean penyakit HIV yang menyebabkan neoplasma ganas, kode yang mengklasifikasikan neoplasma ganas harus dituliskan setelah kode yang mengklasifikasikan HIV yang menyebabkan neoplasma ganas dari kategori B21.- Human immunodeficiency virus [HIV] disease resulting in malignant neoplasms. ○ Jika seorang pasien memiliki penyakit HIV yang menyebabkan lebih dari satu neoplasma ganas, kode B21.7 HIV yang menyebabkan beberapa neoplasma ganas harus ditugaskan diikuti oleh kode-kode untuk neoplasma ganas yang spesifik. ○ Contoh pengkodean kasus HIV:a) HIV disease resulting in Pneumocystis jirovecii pneumonia B20.6 HIV disease resulting in Pneumocystis jirovecii pneumonia b) HIV resulting in candidiasis of the mouth B20.4 HIV disease resulting in candidiasis B37.0 Candidal stomatitis c) HIV disease resulting in respiratory tuberculosis and cytomegaloviral disease B20.7 HIV disease resulting in multiple infections A16.9 Respiratory tuberculosis unspecified, without mention of bacteriological or histological confirmation B25.9 Cytomegaloviral disease, unspecified d) HIV disease resulting in Kaposi sarcoma of multiple organs B21.0 HIV disease resulting in Kaposi sarcoma C46.8 Kaposi sarcoma of multiple organs e) HIV disease resulting in Kaposi sarcoma of the palate and Burkitt lymphoma B21.7 HIV disease resulting in multiple malignant neoplasms C46.2 Kaposi sarcoma of palate C83.7 Burkitt lymphoma Berikut merupakan beberapa hal yang perlu diperhatikan dalam pengkodean infeksi seperti:● Dokumentasi medis yang mencatat agen/organisme infeksi tanpa menyebutkan lokasi spesifik infeksi, maka kode dari Bab I Certain infectious and parasitic diseases (A00-B99) ICD-10 harus diberikan untuk menjelaskan dokumentasi medis tersebut. Dalam kasus ini, hanya agen penyebab infeksi yang dikodekan, tanpa menentukan lokasi infeksi. ○ Contoh:Pasien masuk rumah sakit dengan demam dan menggigil. Hasil kultur darah menunjukkan infeksi Staphylococcus, maka gunakan kode A49.0 (Staphylococcal infection, unspecified site) (Infeksi Staphylococcal tanpa lokasi spesifik). ● Dokumentasi medis yang mencatat lokasi infeksi tanpa menyebutkan agen/organisme penyebabnya, maka kode yang digunakan harus berasal dari bab sistem tubuh terkait (Bab VI–XIV dalam ICD-10) yang sesuai dengan lokasi infeksi tersebut. ○ Contoh:Dokter mendiagnosis pasien dengan infeksi pada saluran kemih tanpa menyebutkan agen/organisme penyebab, maka berikan kode N39.0 (Urinary Tract Infection, Site not specified) (Lokasi spesifik infeksi tanpa agen penyebab). ● Dokumentasi medis yang mencatat lokasi infeksi dan agen/organisme, maka kode yang digunakan harus mencerminkan lokasi spesifik infeksi beserta agen penyebabnya. Penerapan kode mengikuti ketentuan berikut:1) Pada indeks alfabetik ICD-10, apabila ada petunjuk untuk menggunakan kombinasi kode Dagger (†) dan Asterisk (*) yang menggabungkan antara penyebab (agen/organisme) dan lokasi infeksi, maka gunakan kode Dagger untuk penyebab penyakit dan kode Asterisk untuk lokasi atau manifestasi infeksinya sesuai sistem Dagger & Asterisk. - Contoh:Pasien dirawat karena infeksi Salmonella, kemudian selama pemulihan mengalami batuk yang memburuk. Dokter mendiagnosis pasien dengan pneumonia akibat infeksi Salmonella, maka gunakan kode A02.2† (calized salmonella infections) sebagai kode utama dan J17.0* (Pneumonia in bacterial diseases classified elsewhere) sebagai kode sekunder. Catatan:Dalam kaidah morbiditas asterisk dapat dipergunakan sebagai primer, jika dia merupakan alasan perawatan. 2) Alfabet Indeks ICD-10 yang mengarahkan ke satu kode, dimana kode tersebut sudah mencakup agen/organisme dan lokasi infeksi, maka gunakan kode tunggal tersebut tanpa perlu menambahkan kode tambahan dari Bab I (B95-B97). - Contoh:Seorang pria 45 tahun mengalami demam tinggi, sakit kepala berat, muntah, dan leher kaku. Pungsi lumbal menunjukkan leukosit meningkat, protein tinggi, dan glukosa rendah. Hasil kultur CSF mengkonfirmasi infeksi Streptococcus tanpa spesifikasi lebih lanjut. Pasien didiagnosa Meningitis Streptococcus, maka gunakan kode G00.2 (Streptococcal meningitis) tanpa tambahan kode dari chapter I (B95- B97). 3) Agen infeksi yang tidak teridentifikasi secara spesifik atau dokumentasi medis yang hanya mencantumkan kategori umum misalnya Streptococcus tanpa sub kelompoknya, maka kode dari B95-B97 dapat digunakan sebagai tambahan untuk menjelaskan jenis patogen. - Contoh:Seorang pria 40 tahun mengalami demam tinggi, sakit kepala berat, dan gangguan kesadaran. Pemeriksaan pungsi lumbal menunjukkan peningkatan leukosit dan protein tinggi dengan hasil kultur CSF menunjukkan infeksi Streptococcus tanpa spesifikasi lebih lanjut. Pasien didiagnosis dengan meningitis bakteri akibat Streptococcus Group D, Maka gunakan kode G00.2 (Streptococcal meningitis) sebagai kode utama dan tambahkan kode B95.2 (Streptococcus group D and enterococcus as the cause of diseases classified to other chapters) sebagai kode sekunder untuk mengidentifikasi jenis patogen spesifik dari streptococcus.', 'Contoh:Pasien masuk rumah sakit dengan demam dan menggigil. Hasil kultur darah menunjukkan infeksi Staphylococcus, maka gunakan kode A49.0 (Staphylococcal infection, unspecified site) (Infeksi Staphylococcal tanpa lokasi spesifik). Contoh:Dokter mendiagnosis pasien dengan infeksi pada saluran kemih tanpa menyebutkan agen/organisme penyebab, maka berikan kode N39.0 (Urinary Tract Infection, Site not specified) (Lokasi spesifik infeksi tanpa agen penyebab). Contoh:Pasien dirawat karena infeksi Salmonella, kemudian selama pemulihan mengalami batuk yang memburuk. Dokter mendiagnosis pasien dengan pneumonia akibat infeksi Salmonella, maka gunakan kode A02.2† (calized salmonella infections) sebagai kode utama dan J17.0* (Pneumonia in bacterial diseases classified elsewhere) sebagai kode sekunder. Catatan:Dalam kaidah morbiditas asterisk dapat dipergunakan sebagai primer, jika dia merupakan alasan perawatan. 2) Alfabet Indeks ICD-10 yang mengarahkan ke satu kode, dimana kode tersebut sudah mencakup agen/organisme dan lokasi infeksi, maka gunakan kode tunggal tersebut tanpa perlu menambahkan kode tambahan dari Bab I (B95-B97). - Contoh:Seorang pria 45 tahun mengalami demam tinggi, sakit kepala berat, muntah, dan leher kaku. Pungsi lumbal menunjukkan leukosit meningkat, protein tinggi, dan glukosa rendah. Hasil kultur CSF mengkonfirmasi infeksi Streptococcus tanpa spesifikasi lebih lanjut. Pasien didiagnosa Meningitis Streptococcus, maka gunakan kode G00.2 (Streptococcal meningitis) tanpa tambahan kode dari chapter I (B95- B97). 3) Agen infeksi yang tidak teridentifikasi secara spesifik atau dokumentasi medis yang hanya mencantumkan kategori umum misalnya Streptococcus tanpa sub kelompoknya, maka kode dari B95-B97 dapat digunakan sebagai tambahan untuk menjelaskan jenis patogen. - Contoh:Seorang pria 40 tahun mengalami demam tinggi, sakit kepala berat, dan gangguan kesadaran. Pemeriksaan pungsi lumbal menunjukkan peningkatan leukosit dan protein tinggi dengan hasil kultur CSF menunjukkan infeksi Streptococcus tanpa spesifikasi lebih lanjut. Pasien didiagnosis dengan meningitis bakteri akibat Streptococcus Group D, Maka gunakan kode G00.2 (Streptococcal meningitis) sebagai kode utama dan tambahkan kode B95.2 (Streptococcus group D and enterococcus as the cause of diseases classified to other chapters) sebagai kode sekunder untuk mengidentifikasi jenis patogen spesifik dari streptococcus.', '3.18', '327', '352', '80b49d3a-71cf-11f1-b543-3a52e86ddc6f', NULL, '2026-10-07 22:30:52', '2026-10-08 15:29:51');
INSERT INTO `dt01_ics_mdc` (`ID`, `DOCUMENT_ID`, `MDC_CODE`, `SORT_ORDER`, `IS_ACTIVE`, `NAME_EN`, `NAME_ID`, `EXPLANATION`, `EXAMPLE`, `CHAPTER_NO`, `PAGE_START`, `PAGE_END`, `CREATED_BY`, `UPDATED_BY`, `CREATED_AT`, `UPDATED_AT`) VALUES ('19', '1', '29', '19', '1', 'Diseases and Disorders of the Circulatory System', 'PENYAKIT DAN GANGGUAN MENTAL', '● Kombinasi kode dagger dan asterisk G30.-† (Alzheimer\'s disease) dan F00* (Dementia in Alzheimer\'s disease) mengklasifikasikan Demensia Alzheimer. Istilah penyakit Alzheimer dan demensia Alzheimer sering digunakan secara bergantian. Namun, mungkin bagi pasien dapat didiagnosis penyakit Alzheimer sebelum menunjukkan gejala klinis demensia. Oleh karena itu, ketika penyakit Alzheimer didokumentasikan dalam catatan medis tanpa menyebutkan demensia, konsultan yang bertanggung jawab harus dikonsultasikan untuk mengonfirmasi keberadaan demensia sebelum penugasan kombinasi dagger dan asterisk G30.-† (Alzheimer\'s disease) dan F00* (Dementia in Alzheimer\'s disease). Contoh:Dementia in early onset Alzheimer disease G30.0† (Alzheimer disease with early onset) F00.0* (Dementia in Alzheimer disease with early onset) ● Setiap kali diagnosis terdokumentasi dari \'delirium\' atau \'keadaan kebingungan akut\' dibuat dalam catatan medis pasien, ini harus dikodekan menggunakan kode ICD-10 yang sesuai. Jika penyebab delirium atau keadaan kebingungan akut diketahui, ini juga harus dikodekan menggunakan kode ICD-10 yang sesuai. Diagnosis terdokumentasi dari \'delirium\' bersama dengan ko-morbiditas/diagnosis terdokumentasi dari \'demensia\' harus dikodekan menggunakan kode F05.1 (Delirium superimposed on dementia). Contoh:Pasien lanjut usia dengan infeksi saluran kemih dan keadaan kebingungan akut. Infeksi saluran kemih diobati dengan antibiotik. N39.0 (Urinary tract infection, site not specified) F05.9 (Delirium, unspecified) ● Dalam MDC 29 terdapat DRG khusus untuk pemberian tindakan Electroconvulsive Therapy (ECT), sehingga koder harus memperhatikan dokumentasi medis dan bukti tata laksana pemberian ECT. - Ketika terdapat diagnosis yang masuk ke dalam MDC 29 dan disertai dengan tindakan ECT dengan kode 94.27, 94.270, dan 94.271, maka akan masuk ke dalam DRG dengan deskripsi w/ECT, misalkan:○ Schizophrenia and Schizoaffective Disorders w/ ECT - Chronic ○ Schizophrenia and Schizoaffective Disorders w/ ECT - Sub Acute', 'Contoh:Dementia in early onset Alzheimer disease G30.0† (Alzheimer disease with early onset) F00.0* (Dementia in Alzheimer disease with early onset) Contoh:Pasien lanjut usia dengan infeksi saluran kemih dan keadaan kebingungan akut. Infeksi saluran kemih diobati dengan antibiotik. N39.0 (Urinary tract infection, site not specified) F05.9 (Delirium, unspecified)', '3.19', '354', '371', '80b49d3a-71cf-11f1-b543-3a52e86ddc6f', NULL, '2026-10-07 22:30:52', '2026-10-08 15:29:51');
INSERT INTO `dt01_ics_mdc` (`ID`, `DOCUMENT_ID`, `MDC_CODE`, `SORT_ORDER`, `IS_ACTIVE`, `NAME_EN`, `NAME_ID`, `EXPLANATION`, `EXAMPLE`, `CHAPTER_NO`, `PAGE_START`, `PAGE_END`, `CREATED_BY`, `UPDATED_BY`, `CREATED_AT`, `UPDATED_AT`) VALUES ('20', '1', '30', '20', '1', 'Factors Influencing Health Status and Other Contacts with Health Services', 'FAKTOR YANG MEMPENGARUHI STATUS KESEHATAN', '● Penggunaan kode Z masih digunakan untuk melengkapi kondisi utama saat dilakukan follow up penyakit dan digunakan untuk terapi pada penyakit seperti kemoterapi, radioterapi, fisioterapi, rehabilitasi medis maupun status persalinan dan bayi baru lahir. Kode-kode Z digunakan sebagai dasar pengajuan klaim, bukan untuk kepentingan statistik penyakit rumah sakit. Oleh karena itu, perlu dilakukan pemisahan secara tegas antara kode untuk klaim dan kode untuk keperluan statistik rumah sakit. ● Untuk Follow Up hanya ada 3 Sub bab kode yang digunakan yaitu:Z08.- Follow-up examination after treatment for malignant neoplasms Z09.- Follow-up examination after treatment for conditions other than malignant neoplasms Z39.- Postpartum care and examination ● Kode dalam kategori Z00-Z13 digunakan pada orang/pasien yang berkunjung untuk pemeriksaan dan investigasi kesehatan dan hanya boleh dicantumkan sebagai diagnosis utama apabila tidak terdapat diagnosis spesifik, komplikasi, cedera, gejala, atau temuan abnormal lainnya yang dapat menjelaskan alasan kunjungan. Apabila ditemukan diagnosis spesifik atau temuan abnormal sebagai hasil investigasi, maka kode Z00–Z13 tidak boleh digunakan.. ● Bila Pasien kontrol pengobatan dengan diagnosa utama yang sama dengan kunjungan sebelumnya maka Kode Z08-Z09.8 digunakan untuk klaim pasien rawat jalan kunjungan “ follow up ”. ● Kode Z37 digunakan untuk kasus persalinan sebagai output delivery pada rekam medis ibu sedangkan Z38 untuk rekam medis bayi. ● Kode Z50 dan Z51 digunakan sebagai penanda untuk kasus Radioterapi, Kemoterapi, dan Rehabilitasi Medis. Kode tersebut dicantumkan sebagai diagnosis primer ataupun sekunder, sesuai konteks klinis dan administratif.', NULL, '3.20', '373', '395', '80b49d3a-71cf-11f1-b543-3a52e86ddc6f', NULL, '2026-10-07 22:30:52', '2026-10-08 15:29:51');
INSERT INTO `dt01_ics_mdc` (`ID`, `DOCUMENT_ID`, `MDC_CODE`, `SORT_ORDER`, `IS_ACTIVE`, `NAME_EN`, `NAME_ID`, `EXPLANATION`, `EXAMPLE`, `CHAPTER_NO`, `PAGE_START`, `PAGE_END`, `CREATED_BY`, `UPDATED_BY`, `CREATED_AT`, `UPDATED_AT`) VALUES ('21', '1', '31', '21', '1', 'Multiple Significant Trauma', 'MULTIPLE SIGNIFICANT TRAUMA', '● Multiple significant trauma merupakan kelompok diagnosis cedera pada regio luka lebih dari satu bagian tubuh. Sama seperti halnya pada MDC 33, kelompok multiple significant trauma tetap berlaku kaidah pengodean sesuai dengan kasus injuri/trauma yang membutuhkan sebab luar dan lokasinya. - Contoh:pasien masuk dengan keluhan pasca jatuh dari pohon kelapa saat mengambil air nira untuk dibuat gula, terdapat luka terbuka pada tulang paha dan perdarahan aktif di kepala. Didiagnosis oleh dokter traumatic subdural haemorrhage dan open fracture of shatft of femur. Kode DU:S06.5 (Traumatic subdural haemorrhage) Kode DS:S72.391 (Open Fracture of shaft of femur, unspecified) (IM) Kode External Cause:W14.03 (Fall from tree, home, while engaged in other types of work). ● Kondisi nonunion/malunion fraktur dengan kondisi fraktur bersamaan. Kode nonunion/malunion fraktur merupakan salah satu kode yang di exclude pada ICD-10 chapter XIX. Jika episode perawatan merujuk pada kondisi untuk malunion, maka dikode M84.0- (Malunion of fracture) dan kode fraktur tidak dikode. (BA 2023) ● Dalam pengodean tindakan amputasi, penting untuk memastikan bahwa kode spesifik yang digunakan sesuai dengan lokasi amputasi. Penggunaan kode 84.91 (Amputation, not otherwise specified) seharusnya dihindari apabila informasi lokasi amputasi tersedia dalam dokumentasi medis. - Contoh:■ Amputasi pada jari tangan selain ibu jari tangan, gunakan kode 84.01 (Amputation and disarticulation of finger). ■ Amputasi pada ibu jari tangan, gunakan kode 84.02 (Amputation and disarticulation of thumb). ■ Amputasi pada jari kaki, gunakan kode 84.11 (Amputation of toe). ● Dalam pengodean tindakan reduksi tertutup pada fraktur, penting untuk membedakan antara fraktur biasa dan fraktur yang melibatkan lempeng epifisis tulang yang terpisah. Kode 79.0- (Closed reduction of fracture without internal fixation) digunakan jika terdapat fraktur dengan lempeng epifisis yang terpisah pada hasil imaging dan laporan operasi. Sedangkan jika tidak ada lempeng epifisis yang terpisah, maka menggunakan kode 79.4- (Closed reduction of separated epiphysis). ● Dalam pengodean tindakan reduksi/manipulasi pada fraktur yang telah terpasang gips, gunakan kode 79.7- (Closed reduction of dislocation) dengan digit keempat mengikuti lokasi anatomis. ● Dalam pengodean tindakan pemasangan cast, penting untuk memastikan bahwa tindakan yang dilakukan sesuai dengan laporan operasi atau tindakan yang memuat informasi ada atau tidaknya pemasangan cast. Jika tindakan yang dilakukan adalah release clubfoot, gunakan kode 83.84 (Release of clubfoot, not elsewhere classified). Jika dilakukan pemasangan cast, gunakan kode 93.53 (Application of pressure dressing).', 'Contoh:pasien masuk dengan keluhan pasca jatuh dari pohon kelapa saat mengambil air nira untuk dibuat gula, terdapat luka terbuka pada tulang paha dan perdarahan aktif di kepala. Didiagnosis oleh dokter traumatic subdural haemorrhage dan open fracture of shatft of femur. Kode DU:S06.5 (Traumatic subdural haemorrhage) Kode DS:S72.391 (Open Fracture of shaft of femur, unspecified) (IM) Kode External Cause:W14.03 (Fall from tree, home, while engaged in other types of work). Contoh:■ Amputasi pada jari tangan selain ibu jari tangan, gunakan kode 84.01 (Amputation and disarticulation of finger). ■ Amputasi pada ibu jari tangan, gunakan kode 84.02 (Amputation and disarticulation of thumb). ■ Amputasi pada jari kaki, gunakan kode 84.11 (Amputation of toe).', '3.21', '397', '408', '80b49d3a-71cf-11f1-b543-3a52e86ddc6f', NULL, '2026-10-07 22:30:52', '2026-10-08 15:29:51');
INSERT INTO `dt01_ics_mdc` (`ID`, `DOCUMENT_ID`, `MDC_CODE`, `SORT_ORDER`, `IS_ACTIVE`, `NAME_EN`, `NAME_ID`, `EXPLANATION`, `EXAMPLE`, `CHAPTER_NO`, `PAGE_START`, `PAGE_END`, `CREATED_BY`, `UPDATED_BY`, `CREATED_AT`, `UPDATED_AT`) VALUES ('22', '1', '32', '22', '1', 'Burns', 'LUKA BAKAR', 'Luka bakar dan korosi yang terjadi pada lokasi yang sama dengan beberapa tingkat keparahan harus dikodekan sesuai tingkat yang paling parah pada area tersebut, menggunakan kode dalam kategori T20-T32 (Burn and Corrosion). Kode dari kategori T31.- (Burns classified according to extent of body surface involved) atau T32.- (Corrosions classified according to extent of body surface involved) harus ditetapkan sebagai kode tambahan dari kode dari kategori T20-T25 (Burns and corrosions of external body surface, specified by site). Jika luka bakar atau korosi melibatkan beberapa area tubuh atau didokumentasikan adanya persentase total luas permukaan tubuh yang terdampak, maka gunakan kode T29.- (Burns and corrosions of multiple body regions) sebagai kode utama. Contoh 1-32 Pasien datang terkena luka bakar tingkat tiga pada tangan (2% dari permukaan tubuh). Dia terkena api unggun di perkemahan hutan pramuka, dirawat selama 3 hari dan dilakukan tindakan debridement 3x di ruang operasi untuk penanganan luka bakarnya. Diagnosis Dokter Koder Memberi Kode Diagnosis Primer Luka bakar tingkat tiga pada tangan (2% dari permukaan tubuh) dari api unggun di perkemahan hutan pramuka T23.3 Burn of third degree of wrist and hand Diagnosis Sekunder - T31.0 Burns involving less than 10% of body surface X03.89 Exposure to controlled fire, not in building or structure, other specified area during unspecified activity copyright@ Pusat pembiayaan kesehatan Kemenkes RI. Dilarang mengcopy atau memperjualbelikan isi dan dokumen ini dalam bentuk apapun 409', NULL, '3.22', '410', '410', '80b49d3a-71cf-11f1-b543-3a52e86ddc6f', NULL, '2026-10-07 22:30:52', '2026-10-08 15:29:51');
INSERT INTO `dt01_ics_mdc` (`ID`, `DOCUMENT_ID`, `MDC_CODE`, `SORT_ORDER`, `IS_ACTIVE`, `NAME_EN`, `NAME_ID`, `EXPLANATION`, `EXAMPLE`, `CHAPTER_NO`, `PAGE_START`, `PAGE_END`, `CREATED_BY`, `UPDATED_BY`, `CREATED_AT`, `UPDATED_AT`) VALUES ('23', '1', '33', '23', '1', 'Injuries, Poisoning and Certain Other Consequences of External Causes', 'INJURIES, POISONING & CERTAIN OTHER CONSEQUENCES OF EXTERNAL CAUSES', '● Dalam kasus luka-luka atau keracunan yang disebabkan oleh faktor eksternal terdapat dalam kolom tabel obat-obatan untuk mengodekan kasus tersebut dengan menggunakan kode-kode berikut:- Kode yang sesuai dari kolom keracunan pada tabel obat-obatan dan bahan kimia ada pada seksi ketiga ICD-10 dan kode kekerasan sesuai yang terletak di Indeks Alfabetic dari Penyebab Eksternal pada seksi kedua. - Kode tambahan untuk tempat kejadian dan aktivitas juga ditetapkan sesuai dengan pedoman yang ada. Contoh:seorang anak terjatuh dari tangga di sekolah saat sedang menuju ruang kelas, terdapat luka robek di pelipis kanan. Diberikan kode S01.8 (Open wound of other parts of head) sebagai diagnosis utama, ditambahkan sebab luarnya sebagai diagnosis sekunder W10.28 (Fall on and from stairs and steps at School, other institution and public administrative area, While engaged in other specified activities). Contoh:laki-laki paruh baya patah tulang paha kanan tertutup setelah kecelakaan mengendarai sepeda motor menabrak mobil di jalan raya saat berangkat kerja. Diberikan kode S72.90 (Fracture of femur, part unspecified, closed) sebagai diagnosis utama, ditambahkan sebab luarnya sebagai diagnosis sekunder V23.42 (Motorcycle rider injured in collision with car, pick-up truck or van, Driver injured in traffic accident, While working for income). ● Catatan:Subdivisi karakter keempat berikut ini digunakan untuk kategori W00-Y34 kecuali Y06-Y07 untuk mengidentifikasi tempat kejadian penyebab eksternal yang relevan. Klasifikasi tambahan berikut disediakan untuk penggunaan opsional dalam posisi karakter tambahan dengan kategori V01-Y34 untuk menunjukkan aktivitas korban saat kejadian. ● Untuk kasus kecelakaan, lihat pada catatan sebelum blok kodenya. The following fourth-character subdivisions are for use with categories V20-V28:.0 Driver injured in nontraffic accident.1 Passenger injured in nontraffic accident.2 Unspecified motorcycle rider injured in nontraffic accident.3 Person injured while boarding or alighting.4 Driver injured in traffic accident.5 Passenger injured in traffic accident.9 Unspecified motorcycle rider injured in traffic accident', 'Contoh:seorang anak terjatuh dari tangga di sekolah saat sedang menuju ruang kelas, terdapat luka robek di pelipis kanan. Diberikan kode S01.8 (Open wound of other parts of head) sebagai diagnosis utama, ditambahkan sebab luarnya sebagai diagnosis sekunder W10.28 (Fall on and from stairs and steps at School, other institution and public administrative area, While engaged in other specified activities). Contoh:laki-laki paruh baya patah tulang paha kanan tertutup setelah kecelakaan mengendarai sepeda motor menabrak mobil di jalan raya saat berangkat kerja. Diberikan kode S72.90 (Fracture of femur, part unspecified, closed) sebagai diagnosis utama, ditambahkan sebab luarnya sebagai diagnosis sekunder V23.42 (Motorcycle rider injured in collision with car, pick-up truck or van, Driver injured in traffic accident, While working for income).', '3.23', '412', '441', '80b49d3a-71cf-11f1-b543-3a52e86ddc6f', NULL, '2026-10-07 22:30:52', '2026-10-08 15:29:51');
INSERT INTO `dt01_ics_mdc` (`ID`, `DOCUMENT_ID`, `MDC_CODE`, `SORT_ORDER`, `IS_ACTIVE`, `NAME_EN`, `NAME_ID`, `EXPLANATION`, `EXAMPLE`, `CHAPTER_NO`, `PAGE_START`, `PAGE_END`, `CREATED_BY`, `UPDATED_BY`, `CREATED_AT`, `UPDATED_AT`) VALUES ('24', '1', '34', '24', '1', 'Neoplasms', 'NEOPLASMA', '● Pada kasus efusi pleura akibat kanker metastatik atau C78.2 (Secondary malignant neoplasm of pleura) hanya digunakan jika hasil pemeriksaan cairan pleura menunjukkan bukti keganasan. Perhatikan juga diagnosis utama atau sekunder lain, apakah sudah pernah ditegakkan primary cancer atau tidak. Jika tidak ada riwayat primary cancer, akan tetapi ditemukan keganasan pada cairan pleura, gunakan kode C38.- (Malignant neoplasm of heart, mediastinum and pleura) sebagai diagnosis utama dengan melakukan konfirmasi ke dokter penanggung jawab pasien. ● Pengodean tindakan biopsi dan eksisi harus disesuaikan dengan jenis prosedur yang benar-benar dilakukan berdasarkan dokumentasi medis. Jika tindakan yang dilakukan adalah biopsi, baik dengan jarum ataupun open biopsi, maka gunakan kode biopsi yang sesuai. Jika tindakan yang dilakukan adalah eksisi, maka gunakan kode eksisi. Dan apabila tindakan yang dilakukan adalah eksisi sekaligus diikuti dengan biopsi, maka kedua tindakan dikodekan secara terpisah sesuai dengan masing-masing jenis tindakan dan anatomi lokasinya. ○ Pada kasus tumor rongga pelvis (D36.7), jika prosedur yang dilakukan adalah eksisi (sebagai tindakan terapeutik) pada rongga pelvis daerah peritonium, gunakan kode 54.4 (Excision or destruction of peritoneal tissue). Jika prosedur yang dilakukan hanya untuk biopsi, gunakan kode 54.23 (Biopsy of peritoneum). Jika berdasarkan hasil patologi anatomi terdapat tindakan eksisi dan dilanjutkan dengan tindakan biopsi, maka menggunakan kode eksisi dan kode biopsi. ○ Pada prosedur eksisi tumor sinonasal, jika hanya dilakukan eksisi tumor sinonasal, gunakan kode 22.6 (Other nasal sinusectomy). Jika dilakukan eksisi tumor sinonasal dan pengangkatan tulang wajah, tambahkan kode 76.39 (Partial ostectomy of other facial bone). Pada kasus tumor hemangioma yang berlokasi di kulit sebagai soft tissue tumor, pastikan kedalaman tindakan eksisi dan lokasi hemangioma pada laporan operasi. Jika eksisi lokal hemangioma pada kulit dan jaringan bawah kulit, gunakan kode tindakan 86.3 (Other local excision or destruction of lesion or tissue of skin and subcutaneous tissue). Jika eksisi luas hemangioma pada kulit dengan melibatkan struktur yang mendasari atau berdekatan, gunakan kode tindakan 86.4 (Radical excision of skin lesion). ○ Pada kasus ekstirpasi tumor mammae, jika prosedur yang dilakukan hanya biopsi dengan jarum, menggunakan kode 85.11 (Closed [percutaneous] [needle] biopsy of breast). Apabila prosedur biopsi yang dilakukan adalah open biopsi, gunakan 85.12 (Open biopsy of breast). Jika prosedur tersebut adalah eksisi tumor atau bagian lain pada payudara (sebagai tindakan terapeutik), gunakan kode 85.2- (Excision or destruction of breast tissue) disesuaikan dengan lokasi eksisinya. Jika pada hasil patologi anatomi dilakukan tindakan eksisi dilanjutkan dengan biopsi, gunakan kode eksisi dan kode biopsi. ○ Pada kasus ekstirpasi besar tumor pedis, gunakan kode 77.68 (Local excision of lesion or tissue of bone, tarsals and metatarsals) apabila prosedur yang dilakukan adalah pengangkatan lesi/tumor yang berasal dari jaringan tulang tarsal dan metatarsal. Gunakan kode 77.48 (Biopsy of bone, tarsals and metatarsals) apabila prosedur yang dilakukan adalah prosedur eksisi dengan tujuan biopsi dari tulang tarsal dan metatarsal. ● Kemoterapi dalam iDRG terbagi menjadi dua pelayanan yaitu kemoterapi oral dan injeksi. Pasien yang datang baik ke rawat jalan dan mendapatkan obat kemoterapi oral ataupun mendapatkan kemoterapi injeksi, maka menggunakan kode Z51.1 (Chemotherapy Session for Neoplasm) sebagai diagnosis utama dan kode neoplasma dikode sebagai diagnosis sekunder. Contoh 1:Diagnosis utama:Kemoterapi oral di rawat jalan Diagnosis sekunder:Ca Paru Tindakan:- Dikode Z51.1 (Chemotherapy Session for Neoplasm) sebagai diagnosis utama dan Ca Paru C34.9 (Bronchus or lung, unspecified) dikode sebagai diagnosis sekunder. Contoh 2:Diagnosis utama:Kemoterapi Diagnosis sekunder:Ca. Payudara Tindakan:injeksi kemoterapi Dikode Z51.1 (Chemotherapy Session for Neoplasm) sebagai diagnosis utama, C50.9 (Breast, Unspecified) sebagai diagnosis sekunder dan 99.25 (Injection or infusion of cancer chemotherapeutic substance) sebagai kode Tindakan/prosedur. ● Pasien yang datang ke rawat jalan atau rawat inap hanya untuk radioterapi maka menggunakan kode Z51.0 (Radiotherapy Session) sebagai diagnosis utama dan neoplasma menjadi diagnosis sekunder. Contoh 1:Diagnosis utama:Radioterapi Diagnosis sekunder:Ca. Payudara Tindakan:Radioterapi dengan Photon Dikode Z51.0 (Radiotherapy Session) sebagai diagnosis utama, C50.9 (Breast, Unspecified) sebagai diagnosis sekunder dan 92.24 (Teleradiotherapy using photons) sebagai kode prosedur. ● Pasien yang dirawat inap dilakukan tindakan operasi yang dilanjutkan dengan kemoterapi dan/atau radioterapi dalam satu episode perawatan maka yang menjadi diagnosis utama adalah yang berhubungan dengan tindakan utama. ● Pasien yang datang untuk dilakukan kemoterapi dan radioterapi dalam satu episode perawatan yang sama, gunakan kode Z51.0 dan Z51.1 serta kode diagnosis cancer nya, dilanjutkan dengan kode tindakan untuk kemoterapi dan radioterapinya misal 99.25 dan 92.2- harus dimasukkan keduanya untuk mendapatkan kelompok kemoterapi dan radioterapi. Contoh 1 Diagnosis utama:Radioterapi dan Kemoterapi injeksi Diagnosis sekunder:Ca. Paru metas ke Otak Tindakan:Radioterapi dengan Photon dan injeksi kemoterapi Kode:Diagnosis utama:Z51.0 (Radiotherapy Session) Diagnosis sekunder:Z51.1 Chemotherapy Session for Neoplasm C34.9 Bronchus or lung, unspecified C79.3 Secondary malignant neoplasm of brain and cerebral meninges Prosedur:99.25 Injection or infusion of cancer chemotherapeutic substance 92.24 Teleradiotherapy using photons 1. Anemia yang disebabkan oleh neoplasma dikodekan sebagai D63.0* (Anaemia in neoplastic disease), dengan kode yang tepat untuk neoplasma sebagai kode tambahan menggunakan (C00–D48†). Pasien pasca kemoterapi atau radioterapi yang datang untuk perbaikan keadaan/kondisi umum yang memerlukan transfusi bisa diberikan kode neoplasma-nya sebagai diagnosis utama dan D63.0* sebagai diagnosis sekunder ditambahkan kode tindakan transfusi darah 99.04 untuk mendapatkan kelompok Neoplasma + Blood Transfusion. Contoh 1:Diagnosis utama:Anemia Diagnosis sekunder:Ca. Hati Tindakan:Transfusi PRC Dikode C22.9 (Liver, unspecified) sebagai diagnosis utama, D63.0* (Anaemia in neoplastic disease) sebagai diagnosis sekunder dan 99.04 (Transfusion of packed cells) sebagai kode prosedur. 2. Anemia tidak boleh dikodekan dalam gangguan darah neoplastik yang telah di exclude (dikecualikan) dalam ICD 10 dalam kasus diagnosis dan kode ICD berikut ini:D46.-:Myelodysplastic syndromes D47.1:Chronic myeloproliferative disease C92.0:Acute myeloblastic leukaemia [AML] C92.1:Chronic myeloid leukaemia [CML], BCR/ABL-positive C92.2:Atypical chronic myeloid leukaemia, BCR/ABL- negative C93.1:Chronic myelomonocytic leukaemia C94.0:Acute erythroid leukaemia Selain kode - kode ICD diatas maka Anemia bisa dikode sebagai diagnosis sekunder 3. 99.25 sudah termasuk Chemoembolization, sehingga untuk TACE dibuat IM 99.250 (Transcatheter Arterial Chemoembolization) (IM) 4. Dalam hal dilakukan 3D CT Simulator sudah dibuatkan kode baru 88.380 jika menggunakan kontras tambahkan kode 99.290. 5. Layanan Kedokteran Nuklir dibagi menjadi 2 kelompok, yang pertama adalah Nuclear Medicine dengan kode tindakan 92.28 Injection or instillation of radioisotopes dan 92.29 Other radiotherapeutic procedure. Yang kedua adalah Nuclear Diagnostic dengan kode tindakan 92.50 Non-Imaging Nuclear Medicine Thyroid Function Test (IM), 92.51 Non-Imaging Nuclear Medicine Thyroid Cancer Marker (IM), 92.52 Non-Imaging Nuclear Medicine Thyroid Antibody Test (IM) dan 92.01 sampai dengan 92.19. Tata cara pengodean pada pelayanan Kedokteran Nuklir harus ditambahkan dengan kode IM Farmakoterapinya tanpa diawali dengan kode Z51.0 Radiotherapy Session.', NULL, '3.24', '443', '461', '80b49d3a-71cf-11f1-b543-3a52e86ddc6f', NULL, '2026-10-07 22:30:52', '2026-10-08 15:29:51');
INSERT INTO `dt01_ics_mdc` (`ID`, `DOCUMENT_ID`, `MDC_CODE`, `SORT_ORDER`, `IS_ACTIVE`, `NAME_EN`, `NAME_ID`, `EXPLANATION`, `EXAMPLE`, `CHAPTER_NO`, `PAGE_START`, `PAGE_END`, `CREATED_BY`, `UPDATED_BY`, `CREATED_AT`, `UPDATED_AT`) VALUES ('25', '1', '35', '25', '1', 'Rehabilitation', 'REHABILITASI MEDIS', 'Kunjungan fisioterapi dalam satu hari yang sama dengan rehabilitasi medis memiliki iDRG yang berbeda dengan asesmen kunjungan awal maupun kontrol ulang pada poliklinik spesialis. Ketentuan rehabilitasi medis diatur sebagai berikut. 1. Kriteria pertama, pasien dalam satu hari yang sama berkunjung ke poliklinik spesialis untuk mendapatkan penegakan diagnosis dan terapi, kemudian dirujuk ke klinik rehabilitasi medis untuk konsultasi dan mendapatkan rekomendasi untuk fisioterapi. 2. Kriteria kedua, pasien yang dalam satu hari yang sama berkunjung ke klinik rehabilitasi medis untuk konsultasi dan mendapatkan layanan fisioterapi. 3. Kriteria ketiga, pasien yang berkunjung untuk mendapatkan layanan fisioterapi. 4. Kriteria keempat, pasien yang berkunjung ke klinik rehabilitasi untuk konsultasi dan/atau re-asesmen dan mendapatkan rekomendasi untuk fisioterapi. Contoh kasus:1. Pasien berkunjung ke klinik spesialis orthopedi dengan keluhan nyeri lutut memberat ketika beraktifitas. Dokter spesialis ortopedi mendiagnosis dengan OA Genu dan diberikan obat untuk mengurangi nyeri, foto lutut, cek darah lengkap, dan dirujuk ke dokter spesialis rehabilitasi medis pada hari yang sama. Diagnosis Utama:OA Genu Diagnosis Sekunder:konsultasi rehabilitasi medis tindakan:Foto lutut, cek darah, dan konsultasi Maka gunakan:- Kode M17.9 (Gonarthrosis, unspecified) sebagai diagnosis utama - Kode Z50.1 (Other physical therapy) sebagai diagnosis sekunder - 89.07 (Consultation, described as comprehensive) sebagai kode tindakan - 89,071 (Other Specialist Consultation (IM)) sebagai kode tindakan - 90.59 (Microscopic examination of blood, other microscopic examination) sebagai kode tindakan - 88.27 (Skeletal x-ray of thigh, knee, and lower leg) sebagai kode tindakan 2. Pasien berkunjung ke klinik spesialis rehabilitasi medis dengan keluhan nyeri tulang belakang setelah berkunjung ke dokter syaraf untuk dilakukan fisioterapi. Dokter spesialis rehabilitasi medis mendiagnosis LBP kemudian dilakukan uji fungsi dan asesmen untuk fisioterapi serta dilakukan tindakan US dan TENS di hari yang sama. Diagnosis Utama:konsultasi rehabilitasi medis dan uji fungsi Diagnosis Sekunder:LBP tindakan:uji fungsi, fisioterapi US, dan TENS, Maka gunakan:- Kode Z50.1 (Other physical therapy) sebagai diagnosis utama - Kode M54.5 (Low back pain) sebagai diagnosis sekunder - 89.07 (Consultation, described as comprehensive) sebagai kode tindakan - 93.01 Functional evaluation sebagai kode tindakan copyright@ Pusat pembiayaan kesehatan Kemenkes RI. Dilarang mengcopy atau memperjualbelikan isi dan dokumen ini dalam bentuk apapun 463', NULL, '3.25', '463', '464', '80b49d3a-71cf-11f1-b543-3a52e86ddc6f', NULL, '2026-10-07 22:30:52', '2026-10-08 15:29:51');
INSERT INTO `dt01_ics_mdc` (`ID`, `DOCUMENT_ID`, `MDC_CODE`, `SORT_ORDER`, `IS_ACTIVE`, `NAME_EN`, `NAME_ID`, `EXPLANATION`, `EXAMPLE`, `CHAPTER_NO`, `PAGE_START`, `PAGE_END`, `CREATED_BY`, `UPDATED_BY`, `CREATED_AT`, `UPDATED_AT`) VALUES ('26', '1', '36', '26', '1', 'Ungroupable or Unrelated', 'UNGROUPABLE ATAU UNRELATED', 'Ungroupable atau unrelated akan muncul ketika sistem grouper tidak bisa menemukan kecocokan antara kode diagnosis dan tindakan yang dimasukkan kedalam sistem. Sesuai dengan aturan pada ICD-10 diantaranya ada beberapa kode yang hanya bisa dipakai untuk laki-laki, perempuan, bayi baru lahir maupun berdasarkan rentang usia. Jika ditemukan ketidaksesuaian tersebut, maka sistem secara otomatis akan masuk ke MDC 36. Dalam kondisi error grouping (Ungroupable atau unrelated), pengode (coder) dapat memperbaiki kesalahan tersebut dan menginputnya ke dalam sistem sesuai iDRG. Pengode (coder) diharapkan mampu menerapkan etika pengodingan sesuai dengan ICD-10 versi 2010 tidak hanya berdasarkan hafalan atau catatan dari kode yang sering muncul. Hal ini diharapkan mampu meminimalisir adanya error grouping karena yang paling sering terjadi, pengode (coder) tidak memasukkan code also atau modifier lain yang tidak berdampak signifikan pada grouper terdahulu.', NULL, '3.26', '466', '478', '80b49d3a-71cf-11f1-b543-3a52e86ddc6f', NULL, '2026-10-07 22:30:52', '2026-10-08 15:29:51');
