INSERT INTO `dt01_ics_coding_rule` (`ID`, `SECTION_ID`, `RULE_SEQ`, `RULE_TYPE`, `CONDITION_TEXT`, `INSTRUCTION_TEXT`, `IS_MANDATORY`, `AGE_CONDITION`, `SEX_CONDITION`, `SOURCE_TEXT`, `PAGE_PRINTED`, `PAGE_PDF`) VALUES ('1', '1', '1', 'SELECT_BY_CONDITION', 'Meningitis non infeksi akibat obat atau metastasis kanker', 'Meningitis non infeksi akibat obat atau metastasis kanker harus dikodekan sesuai dengan etiologi spesifik.', '0', NULL, NULL, 'Meningitis non infeksi akibat obat atau metastasis kanker harus dikodekan sesuai dengan etiologi spesifik.', '66', '67');
INSERT INTO `dt01_ics_coding_rule` (`ID`, `SECTION_ID`, `RULE_SEQ`, `RULE_TYPE`, `CONDITION_TEXT`, `INSTRUCTION_TEXT`, `IS_MANDATORY`, `AGE_CONDITION`, `SEX_CONDITION`, `SOURCE_TEXT`, `PAGE_PRINTED`, `PAGE_PDF`) VALUES ('2', '1', '2', 'SELECT_BY_CONDITION', 'Dokter mendiagnosis \"bacterial meningitis\" tetapi tidak diketahui jenis bakterinya', 'Jika dokter mendiagnosis \"bacterial meningitis\" tetapi tidak diketahui jenis bakterinya, maka dapat menggunakan kode G00.9 (Bacterial meningitis, unspecified).', '0', NULL, NULL, 'Jika dokter mendiagnosis \"bacterial meningitis\" tetapi tidak diketahui jenis bakterinya, maka dapat menggunakan kode G00.9 (Bacterial meningitis, unspecified). Namun, jika hasil pemeriksaan mengidentifikasi adanya jenis bakteri spesifik, misalnya pneumococcal, maka dapat menggunakan kode G00.1 (Pneumococcal meningitis). Jika tidak dilakukan pemeriksaan kultur, maka dapat menggunakan kode G03.9.', '66', '67');
INSERT INTO `dt01_ics_coding_rule` (`ID`, `SECTION_ID`, `RULE_SEQ`, `RULE_TYPE`, `CONDITION_TEXT`, `INSTRUCTION_TEXT`, `IS_MANDATORY`, `AGE_CONDITION`, `SEX_CONDITION`, `SOURCE_TEXT`, `PAGE_PRINTED`, `PAGE_PDF`) VALUES ('3', '1', '3', 'SELECT_BY_CONDITION', 'Hasil pemeriksaan mengidentifikasi adanya jenis bakteri spesifik (misalnya pneumococcal)', 'Jika hasil pemeriksaan mengidentifikasi adanya jenis bakteri spesifik, misalnya pneumococcal, maka dapat menggunakan kode G00.1 (Pneumococcal meningitis).', '0', NULL, NULL, 'Jika dokter mendiagnosis \"bacterial meningitis\" tetapi tidak diketahui jenis bakterinya, maka dapat menggunakan kode G00.9 (Bacterial meningitis, unspecified). Namun, jika hasil pemeriksaan mengidentifikasi adanya jenis bakteri spesifik, misalnya pneumococcal, maka dapat menggunakan kode G00.1 (Pneumococcal meningitis). Jika tidak dilakukan pemeriksaan kultur, maka dapat menggunakan kode G03.9.', '66', '67');
INSERT INTO `dt01_ics_coding_rule` (`ID`, `SECTION_ID`, `RULE_SEQ`, `RULE_TYPE`, `CONDITION_TEXT`, `INSTRUCTION_TEXT`, `IS_MANDATORY`, `AGE_CONDITION`, `SEX_CONDITION`, `SOURCE_TEXT`, `PAGE_PRINTED`, `PAGE_PDF`) VALUES ('4', '1', '4', 'SELECT_BY_CONDITION', 'Tidak dilakukan pemeriksaan kultur', 'Jika tidak dilakukan pemeriksaan kultur, maka dapat menggunakan kode G03.9.', '0', NULL, NULL, 'Jika dokter mendiagnosis \"bacterial meningitis\" tetapi tidak diketahui jenis bakterinya, maka dapat menggunakan kode G00.9 (Bacterial meningitis, unspecified). Namun, jika hasil pemeriksaan mengidentifikasi adanya jenis bakteri spesifik, misalnya pneumococcal, maka dapat menggunakan kode G00.1 (Pneumococcal meningitis). Jika tidak dilakukan pemeriksaan kultur, maka dapat menggunakan kode G03.9.', '66', '67');
INSERT INTO `dt01_ics_coding_rule` (`ID`, `SECTION_ID`, `RULE_SEQ`, `RULE_TYPE`, `CONDITION_TEXT`, `INSTRUCTION_TEXT`, `IS_MANDATORY`, `AGE_CONDITION`, `SEX_CONDITION`, `SOURCE_TEXT`, `PAGE_PRINTED`, `PAGE_PDF`) VALUES ('8', '2', '1', 'SELECT_BY_CONDITION', 'Myelitis viral, misalnya cytomegalovirus', 'Pada kasus myelitis viral (misalnya cytomegalovirus), dapat menggunakan kode G05.1* sebagai diagnosis tambahan dan kode virusnya sebagai diagnosis utama.', NULL, NULL, NULL, 'Pada kasus myelitis viral (misalnya cytomegalovirus), dapat menggunakan kode G05.1* (Encephalitis, myelitis, and encephalomyelitis in viral diseases classified elsewhere) sebagai diagnosis tambahan dan kode virusnya sebagai diagnosis utama.', '66', '67');
INSERT INTO `dt01_ics_coding_rule` (`ID`, `SECTION_ID`, `RULE_SEQ`, `RULE_TYPE`, `CONDITION_TEXT`, `INSTRUCTION_TEXT`, `IS_MANDATORY`, `AGE_CONDITION`, `SEX_CONDITION`, `SOURCE_TEXT`, `PAGE_PRINTED`, `PAGE_PDF`) VALUES ('9', '2', '2', 'SELECT_BY_CONDITION', 'Dokter mendiagnosis \"viral transverse myelitis\" tanpa menyebutkan jenis virus', 'Pada kasus myelitis transverse viral, jika dokter mendiagnosis \"viral transverse myelitis\" tanpa menyebutkan jenis virusnya, maka dapat menggunakan kode G04.3 (Viral transverse myelitis, unspecified) (IM).', NULL, NULL, NULL, 'Pada kasus myelitis transverse viral, jika dokter mendiagnosis \"viral transverse myelitis\" tanpa menyebutkan jenis virusnya, maka dapat menggunakan kode G04.3 (Viral transverse myelitis, unspecified) (IM). Namun, jika virus penyebab diketahui, maka dapat menggunakan kode B00.4† (Herpesviral encephalitis) + G05.1* (Encephalitis, myelitis, and encephalomyelitis in viral diseases classified elsewhere).', '66', '67');
INSERT INTO `dt01_ics_coding_rule` (`ID`, `SECTION_ID`, `RULE_SEQ`, `RULE_TYPE`, `CONDITION_TEXT`, `INSTRUCTION_TEXT`, `IS_MANDATORY`, `AGE_CONDITION`, `SEX_CONDITION`, `SOURCE_TEXT`, `PAGE_PRINTED`, `PAGE_PDF`) VALUES ('10', '2', '3', 'SELECT_BY_CONDITION', 'Myelitis transverse viral dengan virus penyebab diketahui', 'Jika virus penyebab myelitis transverse viral diketahui, maka dapat menggunakan kode B00.4† + G05.1*.', NULL, NULL, NULL, 'Pada kasus myelitis transverse viral, jika dokter mendiagnosis \"viral transverse myelitis\" tanpa menyebutkan jenis virusnya, maka dapat menggunakan kode G04.3 (Viral transverse myelitis, unspecified) (IM). Namun, jika virus penyebab diketahui, maka dapat menggunakan kode B00.4† (Herpesviral encephalitis) + G05.1* (Encephalitis, myelitis, and encephalomyelitis in viral diseases classified elsewhere).', '66', '67');
INSERT INTO `dt01_ics_coding_rule` (`ID`, `SECTION_ID`, `RULE_SEQ`, `RULE_TYPE`, `CONDITION_TEXT`, `INSTRUCTION_TEXT`, `IS_MANDATORY`, `AGE_CONDITION`, `SEX_CONDITION`, `SOURCE_TEXT`, `PAGE_PRINTED`, `PAGE_PDF`) VALUES ('11', '2', '4', 'SELECT_BY_CONDITION', 'Dokter mendiagnosis \"acute transverse myelitis\" tanpa penyebab infeksi virus', 'Pada kasus myelitis transverse acute non-viral, jika dokter mendiagnosis \"acute transverse myelitis\" tanpa penyebab infeksi virus, maka dapat menggunakan kode G37.3 (Acute transverse myelitis in demyelinating disease of the central nervous system).', NULL, NULL, NULL, 'Pada kasus myelitis transverse acute non-viral, jika dokter mendiagnosis \"acute transverse myelitis\" tanpa penyebab infeksi virus, maka dapat menggunakan kode G37.3 (Acute transverse myelitis in demyelinating disease of the central nervous system). Jika terkait penyakit demyelination misalnya, multiple sclerosis, maka dapat menggunakan kode G35 (Multiple sclerosis). Jika penyebab tidak diketahui, maka dapat menggunakan kode yang sesuai dengan diagnosis klinis utama.', '66', '67');
INSERT INTO `dt01_ics_coding_rule` (`ID`, `SECTION_ID`, `RULE_SEQ`, `RULE_TYPE`, `CONDITION_TEXT`, `INSTRUCTION_TEXT`, `IS_MANDATORY`, `AGE_CONDITION`, `SEX_CONDITION`, `SOURCE_TEXT`, `PAGE_PRINTED`, `PAGE_PDF`) VALUES ('12', '2', '5', 'SELECT_BY_CONDITION', 'Myelitis transverse akut terkait penyakit demyelination, misalnya multiple sclerosis', 'Jika myelitis transverse akut terkait penyakit demyelination, misalnya multiple sclerosis, maka dapat menggunakan kode G35 (Multiple sclerosis).', NULL, NULL, NULL, 'Pada kasus myelitis transverse acute non-viral, jika dokter mendiagnosis \"acute transverse myelitis\" tanpa penyebab infeksi virus, maka dapat menggunakan kode G37.3 (Acute transverse myelitis in demyelinating disease of the central nervous system). Jika terkait penyakit demyelination misalnya, multiple sclerosis, maka dapat menggunakan kode G35 (Multiple sclerosis). Jika penyebab tidak diketahui, maka dapat menggunakan kode yang sesuai dengan diagnosis klinis utama.', '66', '67');
INSERT INTO `dt01_ics_coding_rule` (`ID`, `SECTION_ID`, `RULE_SEQ`, `RULE_TYPE`, `CONDITION_TEXT`, `INSTRUCTION_TEXT`, `IS_MANDATORY`, `AGE_CONDITION`, `SEX_CONDITION`, `SOURCE_TEXT`, `PAGE_PRINTED`, `PAGE_PDF`) VALUES ('13', '2', '6', 'SELECT_BY_CONDITION', 'Penyebab myelitis transverse akut tidak diketahui', 'Jika penyebab tidak diketahui, maka dapat menggunakan kode yang sesuai dengan diagnosis klinis utama.', NULL, NULL, NULL, 'Pada kasus myelitis transverse acute non-viral, jika dokter mendiagnosis \"acute transverse myelitis\" tanpa penyebab infeksi virus, maka dapat menggunakan kode G37.3 (Acute transverse myelitis in demyelinating disease of the central nervous system). Jika terkait penyakit demyelination misalnya, multiple sclerosis, maka dapat menggunakan kode G35 (Multiple sclerosis). Jika penyebab tidak diketahui, maka dapat menggunakan kode yang sesuai dengan diagnosis klinis utama.', '66', '67');
INSERT INTO `dt01_ics_coding_rule` (`ID`, `SECTION_ID`, `RULE_SEQ`, `RULE_TYPE`, `CONDITION_TEXT`, `INSTRUCTION_TEXT`, `IS_MANDATORY`, `AGE_CONDITION`, `SEX_CONDITION`, `SOURCE_TEXT`, `PAGE_PRINTED`, `PAGE_PDF`) VALUES ('15', '3', '1', 'SELECT_BY_CONDITION', 'Abscess atau granuloma ditemukan di otak, pada lokasi epidural, extradural, atau subdural', 'Jika ditemukan abscess atau granuloma di otak, baik yang berlokasi di epidural, extradural, maupun subdural, maka dapat menggunakan kode G06.0 (Intracranial abscess and granuloma).', NULL, NULL, NULL, 'Jika ditemukan abscess atau granuloma di otak, baik yang berlokasi di epidural, extradural, maupun subdural, maka dapat menggunakan kode G06.0 (Intracranial abscess and granuloma).', '67', '68');
INSERT INTO `dt01_ics_coding_rule` (`ID`, `SECTION_ID`, `RULE_SEQ`, `RULE_TYPE`, `CONDITION_TEXT`, `INSTRUCTION_TEXT`, `IS_MANDATORY`, `AGE_CONDITION`, `SEX_CONDITION`, `SOURCE_TEXT`, `PAGE_PRINTED`, `PAGE_PDF`) VALUES ('16', '3', '2', 'SELECT_BY_CONDITION', 'Abses atau granuloma ditemukan di sumsum tulang belakang, pada lokasi epidural, extradural, atau subdural', 'Jika abses atau granuloma ditemukan di sumsum tulang belakang, baik yang berlokasi di epidural, extradural, maupun subdural, maka dapat menggunakan kode G06.1 (Intraspinal abscess and granuloma).', NULL, NULL, NULL, 'Jika abses atau granuloma ditemukan di sumsum tulang belakang, baik yang berlokasi di epidural, extradural, maupun subdural, maka dapat menggunakan kode G06.1 (Intraspinal abscess and granuloma).', '67', '68');
INSERT INTO `dt01_ics_coding_rule` (`ID`, `SECTION_ID`, `RULE_SEQ`, `RULE_TYPE`, `CONDITION_TEXT`, `INSTRUCTION_TEXT`, `IS_MANDATORY`, `AGE_CONDITION`, `SEX_CONDITION`, `SOURCE_TEXT`, `PAGE_PRINTED`, `PAGE_PDF`) VALUES ('17', '3', '3', 'SELECT_BY_CONDITION', 'Penyebab infeksi diketahui contoh abses otak akibat amoeba', 'Jika penyebab infeksi diketahui, gunakan kode etiologi sebagai diagnosis utama dan dapat tambahkan kode abses atau granuloma. Untuk abses otak akibat amoeba, dapat menggunakan A06.6† sebagai diagnosis utama, diikuti G07* sebagai penanda kondisi komplementer.', NULL, NULL, NULL, 'Jika penyebab infeksi diketahui, maka kode etiologi harus digunakan sebagai diagnosis utama, dan dapat menambahkan kode abses atau granuloma. Sebagai contoh, jika abses otak disebabkan oleh amoeba, maka dapat menggunakan kode A06.6† (Amoebic brain abscess) sebagai diagnosis utama, kemudian dapat diikuti oleh kode G07* (Intracranial and intraspinal abscess and granuloma in diseases classified elsewhere) sebagai penanda kondisi komplementer.', '67', '68');
INSERT INTO `dt01_ics_coding_rule` (`ID`, `SECTION_ID`, `RULE_SEQ`, `RULE_TYPE`, `CONDITION_TEXT`, `INSTRUCTION_TEXT`, `IS_MANDATORY`, `AGE_CONDITION`, `SEX_CONDITION`, `SOURCE_TEXT`, `PAGE_PRINTED`, `PAGE_PDF`) VALUES ('18', '4', '1', 'NOTE', 'Kondisi sisa (sekuel) penyakit sistem saraf pusat yang diklasifikasikan pada G00-G08.', 'Gunakan G09 untuk mencatat kondisi sisa akibat penyakit sistem saraf pusat yang diklasifikasikan pada G00-G08 selama kode asal tidak bertanda asterisk (*). G09 mencakup kondisi yang dinyatakan sebagai sekuel atau late effect, atau yang masih ada satu tahun atau lebih setelah penyakit awal. G09 tidak digunakan sebagai kode utama jika kondisi sisa telah dicatat secara spesifik pada pengodean kondisi sisa, G09 dapat digunakan sebagai kode tambahan opsional. Kondisi sisa dari G01*, G02*, G05*, dan G07* tidak dikodekan ke G09, melainkan ke kategori sekuel kondisi dasar yang sesuai, misalnya B90-B94.', NULL, NULL, NULL, 'Kode G09 digunakan untuk mencatat kondisi sisa yang disebabkan oleh penyakit pada sistem saraf pusat yang diklasifikasikan di G00-G08, selama kode asalnya tidak bertanda asterisk (*). Kode ini mencakup kondisi sisa yang secara eksplisit dinyatakan sebagai sekuel, late effect, atau kondisi yang masih ada satu tahun atau lebih setelah penyakit awal. Kode G09 tidak digunakan sebagai kode utama jika kondisi sisa (residual) sudah dicatat secara spesifik. Dalam pengodean untuk kondisi sisa, kode G09 dapat digunakan sebagai kode tambahan yang bersifat opsional. Kondisi sisa dari kategori G01*, G02*, G05*, dan G07* tidak boleh dikodekan ke G09, melainkan harus dikodekan ke kategori yang memang disediakan untuk sekuel dari kondisi dasar tersebut, misalnya B90-B94.', '67', '68');
INSERT INTO `dt01_ics_coding_rule` (`ID`, `SECTION_ID`, `RULE_SEQ`, `RULE_TYPE`, `CONDITION_TEXT`, `INSTRUCTION_TEXT`, `IS_MANDATORY`, `AGE_CONDITION`, `SEX_CONDITION`, `SOURCE_TEXT`, `PAGE_PRINTED`, `PAGE_PDF`) VALUES ('19', '5', '1', 'SELECT_BY_CONDITION', 'Parkinsonism disebabkan oleh penggunaan obat tertentu, misalnya neuroleptic atau metoclopramide', 'Jika parkinsonism disebabkan oleh penggunaan obat tertentu, misalnya neuroleptic atau metoclopramide, maka dapat menggunakan kode G21.1 (Other drug-induced secondary parkinsonism) sebagai kode utama dan dapat menambahkan kode eksternal untuk jenis obat yang menjadi penyebabnya, misalnya T43.4 (Butyrophenone and thioxanthene neuroleptics) untuk obat neuroleptic.', NULL, NULL, NULL, 'Jika parkinsonism disebabkan oleh penggunaan obat tertentu (misalnya, neuroleptic atau metoclopramide), maka dapat menggunakan kode G21.1 (Other drug-induced secondary parkinsonism) sebagai kode utama dan dapat menambahkan kode eksternal untuk jenis obat yang menjadi penyebabnya, misalnya T43.4 (Butyrophenone and thioxanthene neuroleptics) untuk obat neuroleptic.', '68', '69');
