  CONSTRAINT `FK_DOC_SUPERSEDES` FOREIGN KEY (`SUPERSEDES_ID`) REFERENCES `dt01_ics_source_document` (`ID`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


